#[cfg(feature = "kernel")]
fn driver_task_shared_store_barrier() {
    fence(Ordering::Release);
    #[cfg(target_arch = "aarch64")]
    // SAFETY: Driver-task rings are shared normal memory across root and linked
    // runtimes. The store barrier publishes command and payload writes before
    // IPC notification makes the sequence observable to the runtime.
    unsafe {
        core::arch::asm!("dmb ishst", options(nostack, preserves_flags));
    }
}

#[cfg(feature = "kernel")]
fn driver_task_shared_load_barrier() {
    fence(Ordering::Acquire);
    #[cfg(target_arch = "aarch64")]
    // SAFETY: Driver-task rings are shared normal memory across root and linked
    // runtimes. The load barrier pairs with runtime completion publication
    // before root consumes the remaining completion fields or frame payload.
    unsafe {
        core::arch::asm!("dmb ishld", options(nostack, preserves_flags));
    }
}

#[cfg(feature = "kernel")]
fn driver_task_ring_publish_barrier(_ring_root_ptr: usize) {
    driver_task_shared_store_barrier();
}

#[cfg(feature = "kernel")]
fn driver_task_ring_clean_root_range(vaddr: usize, len: usize) {
    driver_task_shared_store_barrier();
    let _ = crate::hal::cache::cache_clean(sel4_sys::seL4_CapInitThreadVSpace, vaddr, len);
    driver_task_shared_store_barrier();
}

#[cfg(feature = "kernel")]
fn driver_task_ring_invalidate_root_range(vaddr: usize, len: usize) {
    let _ = crate::hal::cache::cache_invalidate(sel4_sys::seL4_CapInitThreadVSpace, vaddr, len);
    driver_task_shared_load_barrier();
}

#[cfg(feature = "kernel")]
fn driver_task_ring_stage_command_record(
    slot: &DriverTaskCommandSlot,
    ring_root_ptr: usize,
    command_ptr: *mut DriverTaskCommandRecord,
    completion_ptr: *mut DriverTaskCompletionRecord,
    command: DriverTaskCommandRecord,
    completion_reset: DriverTaskCompletionRecord,
) {
    let mut staged_command = command;
    staged_command.sequence = 0;
    // SAFETY: `command_ptr` and `completion_ptr` address fixed records inside
    // the HAL-owned shared ring page. A zero command sequence is the ABI ready
    // bit for linked runtimes that poll the ring before an endpoint wakeup.
    unsafe {
        core::ptr::write_volatile(completion_ptr, completion_reset);
        core::ptr::write_volatile(command_ptr, staged_command);
    }
    driver_task_ring_clear_continuation_grant(slot, ring_root_ptr);
    driver_task_ring_clean_root_range(
        completion_ptr as usize,
        core::mem::size_of::<DriverTaskCompletionRecord>(),
    );
    driver_task_record_cache_clean(slot, core::mem::size_of::<DriverTaskCompletionRecord>());
    driver_task_ring_clean_root_range(
        command_ptr as usize,
        core::mem::size_of::<DriverTaskCommandRecord>(),
    );
    driver_task_record_cache_clean(slot, core::mem::size_of::<DriverTaskCommandRecord>());
    driver_task_ring_publish_barrier(ring_root_ptr);
}

#[cfg(feature = "kernel")]
fn driver_task_ring_commit_command_sequence(
    slot: &DriverTaskCommandSlot,
    ring_root_ptr: usize,
    command_ptr: *mut DriverTaskCommandRecord,
    sequence: u32,
) {
    // SAFETY: `sequence` is the first field of the fixed `repr(C)` command
    // record and is published last so runtimes never consume a partial command.
    unsafe {
        core::ptr::write_volatile(command_ptr as *mut u32, sequence);
    }
    driver_task_ring_clean_root_range(command_ptr as usize, core::mem::size_of::<u32>());
    driver_task_record_cache_clean(slot, core::mem::size_of::<u32>());
    driver_task_ring_publish_barrier(ring_root_ptr);
}

#[cfg(feature = "kernel")]
const fn driver_task_runtime_continuation_fingerprint(command: DriverTaskCommandRecord) -> u32 {
    driver_runtime_continuation_action_fingerprint(
        command.opcode,
        command.flags,
        command.arg0,
        command.arg1,
        command.aux0,
        command.aux1,
        command.budget.max_ops,
        command.budget.max_frames,
        command.budget.max_bytes,
        command.frame.offset,
        command.frame.len,
        command.frame.flags,
    )
}

#[cfg(feature = "kernel")]
fn driver_task_ring_clear_continuation_grant(slot: &DriverTaskCommandSlot, ring_root_ptr: usize) {
    let grant_ptr =
        (ring_root_ptr + usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_OFFSET)) as *mut u32;
    let words = usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_BYTES) / core::mem::size_of::<u32>();
    let mut index = 0usize;
    while index < words {
        // SAFETY: The fixed continuation record lies wholly inside the
        // HAL-owned shared ring page and contains only primitive u32 fields.
        unsafe {
            core::ptr::write_volatile(grant_ptr.add(index), 0);
        }
        index = index.saturating_add(1);
    }
    driver_task_ring_clean_root_range(
        grant_ptr as usize,
        usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_BYTES),
    );
    driver_task_record_cache_clean(slot, usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_BYTES));
}

#[cfg(feature = "kernel")]
fn driver_task_ring_read_continuation_grant(
    ring_root_ptr: usize,
) -> Option<DriverRuntimeContinuationGrant> {
    let base = ring_root_ptr + usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_OFFSET);
    driver_task_ring_invalidate_root_range(
        base,
        usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_BYTES),
    );
    let word = |offset: usize| {
        // SAFETY: Every requested offset is a u32-aligned field of the fixed
        // primitive-only continuation record inside the admitted ring page.
        unsafe { core::ptr::read_volatile((base + offset) as *const u32) }
    };
    let grant_id_offset = core::mem::offset_of!(DriverRuntimeContinuationGrant, grant_id);
    let first_grant_id = word(grant_id_offset);
    if first_grant_id == 0 {
        return None;
    }
    driver_task_shared_load_barrier();
    let grant = DriverRuntimeContinuationGrant {
        magic: word(core::mem::offset_of!(DriverRuntimeContinuationGrant, magic)),
        request_sequence: word(core::mem::offset_of!(
            DriverRuntimeContinuationGrant,
            request_sequence
        )),
        action_fingerprint: word(core::mem::offset_of!(
            DriverRuntimeContinuationGrant,
            action_fingerprint
        )),
        generation: word(core::mem::offset_of!(
            DriverRuntimeContinuationGrant,
            generation
        )),
        grant_id: first_grant_id,
        consumed_grant_id: word(core::mem::offset_of!(
            DriverRuntimeContinuationGrant,
            consumed_grant_id
        )),
    };
    driver_task_shared_load_barrier();
    driver_task_ring_invalidate_root_range(base + grant_id_offset, core::mem::size_of::<u32>());
    (word(grant_id_offset) == first_grant_id
        && grant.magic == DRIVER_RUNTIME_CONTINUATION_GRANT_MAGIC)
        .then_some(grant)
}

#[cfg(feature = "kernel")]
fn driver_task_ring_publish_continuation_grant(
    slot: &DriverTaskCommandSlot,
    ring_root_ptr: usize,
    command: DriverTaskCommandRecord,
    grant_id: u32,
) -> bool {
    if command.sequence == 0 || grant_id == 0 {
        return false;
    }
    let grant = DriverRuntimeContinuationGrant::new(
        command.sequence,
        driver_task_runtime_continuation_fingerprint(command),
        command.aux1,
        grant_id,
    );
    let base = ring_root_ptr + usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_OFFSET);
    let write = |offset: usize, value: u32| {
        // SAFETY: Every requested offset is a u32-aligned field of the fixed
        // primitive-only continuation record inside the admitted ring page.
        unsafe {
            core::ptr::write_volatile((base + offset) as *mut u32, value);
        }
    };
    let grant_id_offset = core::mem::offset_of!(DriverRuntimeContinuationGrant, grant_id);
    let consumed_offset = core::mem::offset_of!(DriverRuntimeContinuationGrant, consumed_grant_id);
    write(grant_id_offset, 0);
    write(consumed_offset, 0);
    driver_task_ring_clean_root_range(base + grant_id_offset, core::mem::size_of::<u32>() * 2);
    driver_task_record_cache_clean(slot, core::mem::size_of::<u32>() * 2);
    for (offset, value) in [
        (
            core::mem::offset_of!(DriverRuntimeContinuationGrant, magic),
            grant.magic,
        ),
        (
            core::mem::offset_of!(DriverRuntimeContinuationGrant, request_sequence),
            grant.request_sequence,
        ),
        (
            core::mem::offset_of!(DriverRuntimeContinuationGrant, action_fingerprint),
            grant.action_fingerprint,
        ),
        (
            core::mem::offset_of!(DriverRuntimeContinuationGrant, generation),
            grant.generation,
        ),
    ] {
        write(offset, value);
    }
    driver_task_ring_clean_root_range(base, grant_id_offset);
    driver_task_record_cache_clean(slot, grant_id_offset);
    write(grant_id_offset, grant.grant_id);
    driver_task_ring_clean_root_range(base + grant_id_offset, core::mem::size_of::<u32>());
    driver_task_record_cache_clean(slot, core::mem::size_of::<u32>());
    true
}

#[cfg(feature = "kernel")]
fn driver_task_ring_publish_command_record(
    slot: &DriverTaskCommandSlot,
    ring_root_ptr: usize,
    command_ptr: *mut DriverTaskCommandRecord,
    completion_ptr: *mut DriverTaskCompletionRecord,
    command: DriverTaskCommandRecord,
    completion_reset: DriverTaskCompletionRecord,
) {
    driver_task_ring_stage_command_record(
        slot,
        ring_root_ptr,
        command_ptr,
        completion_ptr,
        command,
        completion_reset,
    );
    driver_task_ring_commit_command_sequence(slot, ring_root_ptr, command_ptr, command.sequence);
}

#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct DriverTaskRingProgressRecord {
    magic: u32,
    sequence: u32,
    phase: u32,
    aux0: u32,
}

#[cfg(feature = "kernel")]
fn driver_task_ring_read_progress_record(ring_root_ptr: usize) -> DriverTaskRingProgressRecord {
    let progress_ptr = (ring_root_ptr + DRIVER_RUNTIME_RING_PROGRESS_OFFSET as usize) as *const u32;
    driver_task_ring_invalidate_root_range(
        progress_ptr as usize,
        core::mem::size_of::<DriverTaskRingProgressRecord>(),
    );
    // SAFETY: The progress record is a fixed primitive-only record in the
    // HAL-owned ring page and is bounded by the owner-state metadata region.
    unsafe {
        DriverTaskRingProgressRecord {
            magic: core::ptr::read_volatile(progress_ptr),
            sequence: core::ptr::read_volatile(progress_ptr.add(1)),
            phase: core::ptr::read_volatile(progress_ptr.add(2)),
            aux0: core::ptr::read_volatile(progress_ptr.add(3)),
        }
    }
}

#[cfg(feature = "kernel")]
fn driver_task_ring_invalidate_completion_record(ring_root_ptr: usize) {
    driver_task_ring_invalidate_root_range(
        ring_root_ptr + DRIVER_TASK_RING_COMPLETION_OFFSET,
        core::mem::size_of::<DriverTaskCompletionRecord>(),
    );
}

#[cfg(feature = "kernel")]
fn driver_task_read_sequence_committed<T>(
    mut read_sequence: impl FnMut() -> Option<u32>,
    mut read_body: impl FnMut() -> Option<T>,
    mut acquire: impl FnMut(),
) -> Option<(u32, T)> {
    let first_sequence = read_sequence()?;
    acquire();
    let body = read_body()?;
    acquire();
    let second_sequence = read_sequence()?;
    (first_sequence == second_sequence).then_some((second_sequence, body))
}

#[cfg(feature = "kernel")]
struct DriverTaskRingView {
    window: super::MappedRegisterWindow,
}

#[cfg(feature = "kernel")]
impl DriverTaskRingView {
    fn new(ring_root_ptr: usize) -> Option<Self> {
        match super::MappedRegisterWindow::new(ring_root_ptr, DRIVER_TASK_RING_PAGE_BYTES) {
            Ok(window) => Some(Self { window }),
            Err(_) => None,
        }
    }

    fn read_u32(&self, offset: usize) -> Option<u32> {
        match self.window.read_u32(offset) {
            Ok(value) => Some(value),
            Err(_) => None,
        }
    }

    fn read_u16(&self, offset: usize) -> Option<u16> {
        if offset & 1 != 0 {
            return None;
        }
        let aligned = offset & !3;
        let shift = ((offset & 2) * 8) as u32;
        self.read_u32(aligned)
            .map(|word| ((word >> shift) & u32::from(u16::MAX)) as u16)
    }

    fn read_frame(&self, offset: usize) -> Option<DriverFrameDescriptor> {
        Some(DriverFrameDescriptor {
            offset: self.read_u32(offset)?,
            len: self.read_u16(offset.checked_add(core::mem::size_of::<u32>())?)?,
            flags: self.read_u16(
                offset.checked_add(core::mem::size_of::<u32>() + core::mem::size_of::<u16>())?,
            )?,
        })
    }

    fn read_command(&self) -> Option<DriverTaskCommandRecord> {
        let budget_offset = core::mem::offset_of!(DriverTaskCommandRecord, budget);
        Some(DriverTaskCommandRecord {
            sequence: self.read_u32(core::mem::offset_of!(DriverTaskCommandRecord, sequence))?,
            opcode: self.read_u16(core::mem::offset_of!(DriverTaskCommandRecord, opcode))?,
            flags: self.read_u16(core::mem::offset_of!(DriverTaskCommandRecord, flags))?,
            arg0: self.read_u32(core::mem::offset_of!(DriverTaskCommandRecord, arg0))?,
            arg1: self.read_u32(core::mem::offset_of!(DriverTaskCommandRecord, arg1))?,
            aux0: self.read_u32(core::mem::offset_of!(DriverTaskCommandRecord, aux0))?,
            aux1: self.read_u32(core::mem::offset_of!(DriverTaskCommandRecord, aux1))?,
            budget: DriverTaskBudgetGrant {
                max_ops: self.read_u16(
                    budget_offset + core::mem::offset_of!(DriverTaskBudgetGrant, max_ops),
                )?,
                max_frames: self.read_u16(
                    budget_offset + core::mem::offset_of!(DriverTaskBudgetGrant, max_frames),
                )?,
                max_bytes: self.read_u32(
                    budget_offset + core::mem::offset_of!(DriverTaskBudgetGrant, max_bytes),
                )?,
            },
            frame: self.read_frame(core::mem::offset_of!(DriverTaskCommandRecord, frame))?,
        })
    }

    fn read_completion(&self) -> Option<DriverTaskCompletionRecord> {
        let base = DRIVER_TASK_RING_COMPLETION_OFFSET;
        let sequence_offset = base + core::mem::offset_of!(DriverTaskCompletionRecord, sequence);
        let (sequence, (code, detail, result, frame)) = driver_task_read_sequence_committed(
            || self.read_u32(sequence_offset),
            || {
                Some((
                    self.read_u16(base + core::mem::offset_of!(DriverTaskCompletionRecord, code))?,
                    self.read_u16(
                        base + core::mem::offset_of!(DriverTaskCompletionRecord, detail),
                    )?,
                    self.read_u32(
                        base + core::mem::offset_of!(DriverTaskCompletionRecord, result),
                    )?,
                    self.read_frame(
                        base + core::mem::offset_of!(DriverTaskCompletionRecord, frame),
                    )?,
                ))
            },
            driver_task_shared_load_barrier,
        )?;
        if sequence == 0 {
            return None;
        }
        Some(DriverTaskCompletionRecord {
            sequence,
            code,
            detail,
            result,
            frame,
        })
    }

    fn read_dpc_ring(&self) -> Option<DriverRuntimeDpcEventRing> {
        let base = usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET);
        let version_len =
            self.read_u32(base + core::mem::offset_of!(DriverRuntimeDpcEventRing, version))?;
        let mut ring = DriverRuntimeDpcEventRing::empty(
            self.read_u32(base + core::mem::offset_of!(DriverRuntimeDpcEventRing, epoch))?,
        );
        ring.magic =
            self.read_u32(base + core::mem::offset_of!(DriverRuntimeDpcEventRing, magic))?;
        ring.version = (version_len & u32::from(u16::MAX)) as u16;
        ring.len = (version_len >> 16) as u16;
        let producer_offset = base + core::mem::offset_of!(DriverRuntimeDpcEventRing, producer);
        let (producer, ()) = driver_task_read_sequence_committed(
            || self.read_u32(producer_offset),
            || {
                ring.consumer = self
                    .read_u32(base + core::mem::offset_of!(DriverRuntimeDpcEventRing, consumer))?;
                ring.flags =
                    self.read_u32(base + core::mem::offset_of!(DriverRuntimeDpcEventRing, flags))?;
                ring.overruns = self
                    .read_u32(base + core::mem::offset_of!(DriverRuntimeDpcEventRing, overruns))?;
                ring.ack_failures = self.read_u32(
                    base + core::mem::offset_of!(DriverRuntimeDpcEventRing, ack_failures),
                )?;
                let entries_base = base + core::mem::offset_of!(DriverRuntimeDpcEventRing, entries);
                for (index, entry) in ring.entries.iter_mut().enumerate() {
                    let entry_base = entries_base.checked_add(index.checked_mul(
                        core::mem::size_of::<pi4_driver_abi::DriverRuntimeDpcEventEntry>(),
                    )?)?;
                    let sequence_offset = entry_base
                        + core::mem::offset_of!(
                            pi4_driver_abi::DriverRuntimeDpcEventEntry,
                            sequence
                        );
                    let (sequence, (host_int_status, signal_status, reason_flags)) =
                        driver_task_read_sequence_committed(
                            || self.read_u32(sequence_offset),
                            || {
                                Some((
                                    self.read_u32(
                                        entry_base
                                            + core::mem::offset_of!(
                                                pi4_driver_abi::DriverRuntimeDpcEventEntry,
                                                host_int_status
                                            ),
                                    )?,
                                    self.read_u32(
                                        entry_base
                                            + core::mem::offset_of!(
                                                pi4_driver_abi::DriverRuntimeDpcEventEntry,
                                                signal_status
                                            ),
                                    )?,
                                    self.read_u32(
                                        entry_base
                                            + core::mem::offset_of!(
                                                pi4_driver_abi::DriverRuntimeDpcEventEntry,
                                                reason
                                            ),
                                    )?,
                                ))
                            },
                            driver_task_shared_load_barrier,
                        )?;
                    entry.sequence = sequence;
                    entry.host_int_status = host_int_status;
                    entry.signal_status = signal_status;
                    entry.reason = (reason_flags & u32::from(u16::MAX)) as u16;
                    entry.flags = (reason_flags >> 16) as u16;
                }
                Some(())
            },
            driver_task_shared_load_barrier,
        )?;
        ring.producer = producer;
        Some(ring)
    }

    fn zero(&self) -> bool {
        let mut offset = 0usize;
        while offset < DRIVER_TASK_RING_PAGE_BYTES {
            if self.window.write_u32(offset, 0).is_err() {
                return false;
            }
            offset = offset.saturating_add(core::mem::size_of::<u32>());
        }
        true
    }
}

