/// Publish one root CSpace cap backing a driver shared-buffer page.
#[cfg(feature = "kernel")]
pub fn publish_driver_task_shared_frame_cap(
    contract: DriverTaskContract,
    page_index: usize,
    shared_frame_cap: usize,
) {
    publish_driver_task_shared_frame(contract, page_index, shared_frame_cap, 0);
}

/// Publish one root CSpace cap and root mapping backing a shared-buffer page.
#[cfg(feature = "kernel")]
pub fn publish_driver_task_shared_frame(
    contract: DriverTaskContract,
    page_index: usize,
    shared_frame_cap: usize,
    shared_frame_root_ptr: usize,
) {
    if page_index >= DRIVER_TASK_BUS_LINK_SHARED_FRAME_CAPACITY {
        return;
    }
    let Some(task_key) = driver_task_contract_key(contract) else {
        return;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return;
    };
    slot.shared_frame_caps[page_index].store(shared_frame_cap, Ordering::Release);
    slot.shared_frame_root_ptrs[page_index].store(shared_frame_root_ptr, Ordering::Release);
    let required_count = page_index.saturating_add(1);
    let current = slot.shared_frame_count.load(Ordering::Acquire);
    if required_count > current {
        slot.shared_frame_count
            .store(required_count, Ordering::Release);
    }
}

/// Return the endpoint and ring-frame caps for a linked bus-owner runtime.
#[cfg(feature = "kernel")]
#[must_use]
pub fn driver_task_bus_owner_transport_caps(
    contract: DriverTaskContract,
) -> Option<(sel4_sys::seL4_CPtr, sel4_sys::seL4_CPtr)> {
    let task_key = driver_task_contract_key(contract)?;
    let slot = slot_for_task_key(task_key)?;
    let endpoint = slot.endpoint.load(Ordering::Acquire);
    let ring_frame_cap = slot.ring_frame_cap.load(Ordering::Acquire);
    if endpoint == 0 || ring_frame_cap == 0 {
        return None;
    }
    Some((
        endpoint as sel4_sys::seL4_CPtr,
        ring_frame_cap as sel4_sys::seL4_CPtr,
    ))
}

/// Return the endpoint, ring-frame cap, and bounded shared-buffer caps for a
/// linked bus-owner runtime.
#[cfg(feature = "kernel")]
#[must_use]
pub fn driver_task_bus_owner_transport_caps_with_shared(
    contract: DriverTaskContract,
    min_shared_pages: usize,
) -> Option<(
    sel4_sys::seL4_CPtr,
    sel4_sys::seL4_CPtr,
    [sel4_sys::seL4_CPtr; DRIVER_TASK_BUS_LINK_SHARED_FRAME_CAPACITY],
)> {
    if min_shared_pages > DRIVER_TASK_BUS_LINK_SHARED_FRAME_CAPACITY {
        return None;
    }
    let (endpoint, ring_frame_cap) = driver_task_bus_owner_transport_caps(contract)?;
    let task_key = driver_task_contract_key(contract)?;
    let slot = slot_for_task_key(task_key)?;
    if slot.shared_frame_count.load(Ordering::Acquire) < min_shared_pages {
        return None;
    }
    let mut shared_frame_caps = [0; DRIVER_TASK_BUS_LINK_SHARED_FRAME_CAPACITY];
    let mut index = 0usize;
    while index < min_shared_pages {
        let cap = slot.shared_frame_caps[index].load(Ordering::Acquire);
        if cap == 0 {
            return None;
        }
        shared_frame_caps[index] = cap as sel4_sys::seL4_CPtr;
        index = index.saturating_add(1);
    }
    Some((endpoint, ring_frame_cap, shared_frame_caps))
}

/// Return whether CYW43 has irreversible producer authority over the SDIO ring.
#[cfg(feature = "kernel")]
#[must_use]
pub fn sdio_command_ring_delegated_to_cyw43() -> bool {
    slot_for_task_key(DRIVER_TASK_KEY_SDIO_HOST).is_some_and(|slot| {
        slot.ring_producer.load(Ordering::Acquire) == SDIO_RING_PRODUCER_CYW43_RUNTIME
    })
}

/// Read-only root view of the isolated SDIO owner's current DPC ring counters.
#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) struct DriverTaskSdioDpcRingSnapshot {
    /// Generated bus-link epoch recorded by the owner.
    pub epoch: u32,
    /// Sequence after the newest committed owner event.
    pub producer: u32,
    /// Sequence after the newest event consumed by CYW43.
    pub consumer: u32,
    /// Current ABI ring flags.
    pub flags: u32,
    /// Saturating owner overrun counter.
    pub overruns: u32,
    /// Saturating failed IRQ-acknowledgement counter.
    pub ack_failures: u32,
}

#[cfg(feature = "kernel")]
fn stable_sdio_dpc_ring_snapshot(
    first: DriverRuntimeDpcEventRing,
    second: DriverRuntimeDpcEventRing,
) -> Option<DriverTaskSdioDpcRingSnapshot> {
    if first != second || !second.valid() {
        return None;
    }
    Some(DriverTaskSdioDpcRingSnapshot {
        epoch: second.epoch,
        producer: second.producer,
        consumer: second.consumer,
        flags: second.flags,
        overruns: second.overruns,
        ack_failures: second.ack_failures,
    })
}

/// Snapshot the isolated SDIO owner's DPC ring without acquiring write
/// authority. The root mapping is retained only for fail-closed diagnostics;
/// producer and consumer ownership remain exclusively with the child runtimes.
#[cfg(feature = "kernel")]
#[must_use]
pub(crate) fn driver_task_sdio_dpc_ring_snapshot() -> Option<DriverTaskSdioDpcRingSnapshot> {
    let slot = slot_for_task_key(DRIVER_TASK_KEY_SDIO_HOST)?;
    if slot.ring_producer.load(Ordering::Acquire) != SDIO_RING_PRODUCER_CYW43_RUNTIME
        || !driver_runtime_descriptor_seal_registered(DriverTaskHotPath::SdioHost)
        || !driver_runtime_descriptor_seal_registered(DriverTaskHotPath::Cyw43Wifi)
    {
        return None;
    }
    let ring_root_ptr = slot.ring_root_ptr.load(Ordering::Acquire);
    if ring_root_ptr == 0 {
        return None;
    }
    let ring = DriverTaskRingView::new(ring_root_ptr)?;
    let dpc_ptr = ring_root_ptr + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET);
    let dpc_len = core::mem::size_of::<DriverRuntimeDpcEventRing>();
    driver_task_ring_invalidate_root_range(dpc_ptr, dpc_len);
    let first = ring.read_dpc_ring()?;
    driver_task_ring_invalidate_root_range(dpc_ptr, dpc_len);
    let second = ring.read_dpc_ring()?;
    driver_task_shared_load_barrier();
    stable_sdio_dpc_ring_snapshot(first, second)
}

#[cfg(feature = "kernel")]
fn driver_task_engine_init_turn_matches(
    hot_path: DriverTaskHotPath,
    request: u32,
    command: DriverTaskCommandRecord,
    completion: DriverTaskCompletionRecord,
) -> bool {
    request != 0
        && command.sequence == request
        && command.opcode == DriverTaskOpcode::Service.as_u16()
        && command.flags & !DRIVER_TASK_RING_FLAG_ONE_WAY == 0
        && command.arg0 == hot_path.as_u32()
        && command.arg1 == hot_path.role_bit() as u32
        && command.aux0 == DRIVER_RUNTIME_ENGINE_INIT_AUX
        && command.aux1 == 0
        && command.frame.offset == 0
        && command.frame.len == 0
        && command.frame.flags == 0
        && completion.sequence == request
        && completion.code == DriverTaskCompletionCode::Progress.as_u16()
        && completion.result == 1
        && completion.frame.offset == 0
        && completion.frame.len == 0
        && completion.frame.flags == 0
}

#[cfg(feature = "kernel")]
fn driver_task_committed_engine_init_turn(
    slot: &DriverTaskCommandSlot,
    hot_path: DriverTaskHotPath,
) -> Option<(u32, DriverTaskCommandRecord, DriverTaskCompletionRecord)> {
    let request = slot.request_seq.load(Ordering::Acquire);
    let ring_root_ptr = slot.ring_root_ptr.load(Ordering::Acquire);
    if request == 0 || ring_root_ptr == 0 || slot.active.load(Ordering::Acquire) != 0 {
        return None;
    }
    driver_task_ring_invalidate_root_range(
        ring_root_ptr,
        core::mem::size_of::<DriverTaskCommandRecord>(),
    );
    driver_task_ring_invalidate_completion_record(ring_root_ptr);
    let ring = DriverTaskRingView::new(ring_root_ptr)?;
    let command = ring.read_command()?;
    let first_completion = ring.read_completion()?;
    if first_completion.sequence != request as u32 {
        return None;
    }
    driver_task_ring_invalidate_completion_record(ring_root_ptr);
    let completion = ring.read_completion()?;
    if first_completion != completion
        || !driver_task_engine_init_turn_matches(hot_path, request as u32, command, completion)
    {
        return None;
    }
    Some((request as u32, command, completion))
}

#[cfg(feature = "kernel")]
fn sdio_root_command_completion_drained(slot: &DriverTaskCommandSlot) -> bool {
    let request = slot.request_seq.load(Ordering::Acquire);
    request <= SDIO_ROOT_SEQUENCE_MAX
        && driver_task_committed_engine_init_turn(slot, DriverTaskHotPath::SdioHost).is_some()
}

#[cfg(feature = "kernel")]
fn cyw43_engine_init_completion_drained(
    slot: &DriverTaskCommandSlot,
    observed_completion: DriverTaskCompletionRecord,
) -> bool {
    matches!(
        driver_task_committed_engine_init_turn(slot, DriverTaskHotPath::Cyw43Wifi),
        Some((_, _, committed_completion))
            if committed_completion == observed_completion
                && committed_completion.detail == DriverTaskFaultCode::None.as_u16()
    )
}

#[cfg(feature = "kernel")]
fn begin_sdio_producer_handoff(slot: &DriverTaskCommandSlot) -> bool {
    if slot
        .ring_producer
        .compare_exchange(
            SDIO_RING_PRODUCER_ROOT_BOOTSTRAP,
            SDIO_RING_PRODUCER_TRANSITION,
            Ordering::AcqRel,
            Ordering::Acquire,
        )
        .is_err()
    {
        return false;
    }
    if slot.root_ring_writers.load(Ordering::Acquire) != 0
        || slot.active.load(Ordering::Acquire) != 0
    {
        slot.ring_producer
            .store(SDIO_RING_PRODUCER_ROOT_BOOTSTRAP, Ordering::Release);
        return false;
    }
    true
}

#[cfg(feature = "kernel")]
const fn sdio_handoff_must_delete_endpoint(endpoint: usize, recovery_endpoint: usize) -> bool {
    endpoint != 0 && endpoint != recovery_endpoint
}

/// Irreversibly delegate the shared SDIO command ring to the CYW43 runtime.
///
/// Root may use this ring only for descriptor replay and SDIO engine bootstrap.
/// The transition succeeds only after those turns are drained and both sealed
/// peers are admitted. Deleting root's endpoint cap leaves the child receive
/// cap and CYW43's separately installed send-only notification alive for
/// serialized owner service while removing root's steady command authority.
#[cfg(feature = "kernel")]
pub fn handoff_sdio_command_ring_to_cyw43(
    cyw43_engine_completion: DriverTaskCompletionRecord,
) -> bool {
    let Some(slot) = slot_for_task_key(DRIVER_TASK_KEY_SDIO_HOST) else {
        crate::bootstrap::log::force_uart_line(
            "DRIVER_TASK_BUS_LINK_HANDOFF channel=cyw43-sdio status=reject reason=sdio-slot-missing",
        );
        return false;
    };
    if slot.ring_producer.load(Ordering::Acquire) == SDIO_RING_PRODUCER_CYW43_RUNTIME {
        if slot.endpoint.load(Ordering::Acquire) == 0 {
            return true;
        }
        crate::bootstrap::log::force_uart_line(
            "DRIVER_TASK_BUS_LINK_HANDOFF channel=cyw43-sdio status=reject reason=delegated-root-endpoint-present",
        );
        return false;
    }
    if !begin_sdio_producer_handoff(slot) {
        crate::bootstrap::log::force_uart_line(
            "DRIVER_TASK_BUS_LINK_HANDOFF channel=cyw43-sdio status=reject reason=root-producer-not-drained",
        );
        return false;
    }
    let rollback = |reason: &'static str| {
        slot.ring_producer
            .store(SDIO_RING_PRODUCER_ROOT_BOOTSTRAP, Ordering::Release);
        crate::bootstrap::log::force_uart_line(reason);
        false
    };
    let Some(cyw43_slot) = slot_for_task_key(DRIVER_TASK_KEY_CYW43455) else {
        return rollback(
            "DRIVER_TASK_BUS_LINK_HANDOFF channel=cyw43-sdio status=reject reason=cyw43-slot-missing",
        );
    };
    if !driver_runtime_descriptor_seal_registered(DriverTaskHotPath::SdioHost)
        || !driver_runtime_descriptor_seal_registered(DriverTaskHotPath::Cyw43Wifi)
    {
        return rollback(
            "DRIVER_TASK_BUS_LINK_HANDOFF channel=cyw43-sdio status=reject reason=descriptor-seal-missing",
        );
    }
    if !cyw43_engine_init_completion_drained(cyw43_slot, cyw43_engine_completion) {
        return rollback(
            "DRIVER_TASK_BUS_LINK_HANDOFF channel=cyw43-sdio status=reject reason=cyw43-engine-turn-mismatch",
        );
    }
    if !sdio_root_command_completion_drained(slot) {
        return rollback(
            "DRIVER_TASK_BUS_LINK_HANDOFF channel=cyw43-sdio status=reject reason=sdio-engine-turn-mismatch",
        );
    }
    let endpoint = slot.endpoint.load(Ordering::Acquire);
    if endpoint == 0 {
        return rollback(
            "DRIVER_TASK_BUS_LINK_HANDOFF channel=cyw43-sdio status=reject reason=root-endpoint-missing",
        );
    }
    let recovery_endpoint = slot.restart_endpoint.load(Ordering::Acquire);
    if sdio_handoff_must_delete_endpoint(endpoint, recovery_endpoint) {
        let delete_err = crate::sel4::cnode_delete(
            sel4_sys::seL4_CapInitThreadCNode,
            endpoint as sel4_sys::seL4_CPtr,
            crate::sel4::word_bits() as u8,
        );
        if delete_err != sel4_sys::seL4_NoError {
            return rollback(
                "DRIVER_TASK_BUS_LINK_HANDOFF channel=cyw43-sdio status=reject reason=root-endpoint-delete-failed",
            );
        }
    }
    slot.endpoint.store(0, Ordering::Release);
    slot.ring_producer
        .store(SDIO_RING_PRODUCER_CYW43_RUNTIME, Ordering::Release);
    crate::bootstrap::log::force_uart_line(if endpoint == recovery_endpoint {
        "DRIVER_TASK_BUS_LINK_HANDOFF channel=cyw43-sdio from=root-recovery to=cyw43-runtime root_endpoint=hidden-recovery-cap-retained root_submit=disabled sequence_domain=fresh status=ready"
    } else {
        "DRIVER_TASK_BUS_LINK_HANDOFF channel=cyw43-sdio from=root-bootstrap to=cyw43-runtime root_endpoint=deleted root_submit=disabled sequence_domain=delegated status=ready"
    });
    true
}

/// Clear a partially published driver-task transport after bootstrap failure.
#[cfg(feature = "kernel")]
pub fn clear_driver_task_transport(contract: DriverTaskContract) {
    let Some(task_key) = driver_task_contract_key(contract) else {
        return;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return;
    };
    slot.endpoint.store(0, Ordering::Release);
    slot.root_notification.store(0, Ordering::Release);
    slot.ring_root_ptr.store(0, Ordering::Release);
    slot.ring_frame_cap.store(0, Ordering::Release);
    slot.ring_context.store(0, Ordering::Release);
    slot.ring_handler.store(0, Ordering::Release);
    slot.ring_service_kind.store(
        DriverTaskRingServiceKind::None.as_usize(),
        Ordering::Release,
    );
    slot.shared_frame_count.store(0, Ordering::Release);
    let mut index = 0usize;
    while index < DRIVER_TASK_BUS_LINK_SHARED_FRAME_CAPACITY {
        slot.shared_frame_caps[index].store(0, Ordering::Release);
        slot.shared_frame_root_ptrs[index].store(0, Ordering::Release);
        index = index.saturating_add(1);
    }
    slot.tcb.store(0, Ordering::Release);
    slot.restart_entry.store(0, Ordering::Release);
    slot.restart_stack_top.store(0, Ordering::Release);
    slot.restart_task_key.store(0, Ordering::Release);
    slot.restart_endpoint.store(0, Ordering::Release);
    slot.restart_normal_endpoint.store(0, Ordering::Release);
    slot.restart_notification.store(0, Ordering::Release);
    slot.restart_notification_bound.store(0, Ordering::Release);
    slot.restart_irq_handler.store(0, Ordering::Release);
    slot.restart_sdhci_root_ptr.store(0, Ordering::Release);
    slot.steady_priority.store(0, Ordering::Release);
    reset_driver_task_steady_priority_for_bootstrap(slot);
    slot.retained_priority_boost_active
        .store(0, Ordering::Release);
    reset_driver_task_retained_priority_lease_slot(slot);
    slot.active.store(0, Ordering::Release);
    slot.active_command_fingerprint.store(0, Ordering::Release);
    slot.request_seq.store(0, Ordering::Release);
    slot.last_progress_magic.store(0, Ordering::Release);
    slot.last_progress_sequence.store(0, Ordering::Release);
    slot.last_progress_phase.store(0, Ordering::Release);
    slot.last_progress_aux0.store(0, Ordering::Release);
}

#[cfg(feature = "kernel")]
struct DriverTaskPriorityRestore {
    contract: DriverTaskContract,
    tcb: usize,
    steady_priority: u8,
}

#[cfg(feature = "kernel")]
impl Drop for DriverTaskPriorityRestore {
    fn drop(&mut self) {
        let tcb = self.tcb as sel4_sys::seL4_CPtr;
        let priority = self.steady_priority;
        let sched = crate::sel4::set_tcb_sched_params(
            tcb,
            sel4_sys::seL4_CapInitThreadTCB,
            priority,
            priority,
        );
        let prio = crate::sel4::set_tcb_priority(tcb, sel4_sys::seL4_CapInitThreadTCB, priority);
        if sched.is_err() || prio.is_err() {
            let mut line = heapless::String::<192>::new();
            let _ = core::fmt::write(
                &mut line,
                format_args!(
                    "DRIVER_TASK_PRIORITY_RESTORE contract={} tcb=0x{:04x} priority={} status=failed",
                    self.contract.name, self.tcb, priority,
                ),
            );
            crate::bootstrap::log::force_uart_line_raw(line.as_str());
        }
    }
}

#[cfg(feature = "kernel")]
fn boost_driver_task_priority_for_bounded_turn(
    contract: DriverTaskContract,
) -> Option<DriverTaskPriorityRestore> {
    if !physical_pi_driver_task_only_owner_state_active() {
        return None;
    }
    let task_key = driver_task_contract_key(contract)?;
    let slot = slot_for_task_key(task_key)?;
    let tcb = slot.tcb.load(Ordering::Acquire);
    let steady_priority = slot.steady_priority.load(Ordering::Acquire);
    if tcb == 0 || steady_priority == 0 || !driver_task_steady_priority_is_active(slot) {
        return None;
    }
    let steady_priority = steady_priority as u8;
    let boost = PI4_BOUNDED_BOOTSTRAP_PRIORITY;
    if steady_priority >= boost {
        return None;
    }
    let tcb_cap = tcb as sel4_sys::seL4_CPtr;
    if crate::sel4::set_tcb_sched_params(tcb_cap, sel4_sys::seL4_CapInitThreadTCB, boost, boost)
        .is_err()
        || crate::sel4::set_tcb_priority(tcb_cap, sel4_sys::seL4_CapInitThreadTCB, boost).is_err()
    {
        let mut line = heapless::String::<192>::new();
        let _ = core::fmt::write(
            &mut line,
            format_args!(
                "DRIVER_TASK_PRIORITY_BOOST contract={} tcb=0x{:04x} priority={} status=failed",
                contract.name, tcb, boost,
            ),
        );
        crate::bootstrap::log::force_uart_line_raw(line.as_str());
        return None;
    }
    Some(DriverTaskPriorityRestore {
        contract,
        tcb,
        steady_priority,
    })
}

#[cfg(feature = "kernel")]
fn driver_task_bounded_turn_bus_owner(
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
) -> Option<DriverTaskContract> {
    if matches!(contract.kind, DriverTaskKind::WifiNic)
        && command.arg0 == DriverTaskHotPath::Cyw43Wifi.as_u32()
    {
        Some(SDIO_HOST_DRIVER_TASK_CONTRACT)
    } else if matches!(contract.kind, DriverTaskKind::LocalSeatUsb)
        && command.arg0 == DriverTaskHotPath::UsbKeyboard.as_u32()
    {
        Some(PCIE_ROOT_DRIVER_TASK_CONTRACT)
    } else {
        None
    }
}

#[cfg(feature = "kernel")]
fn boost_driver_task_priorities_for_bounded_turn(
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
) -> (
    Option<DriverTaskPriorityRestore>,
    Option<DriverTaskPriorityRestore>,
) {
    let primary = boost_driver_task_priority_for_bounded_turn(contract);
    let bus_owner = driver_task_bounded_turn_bus_owner(contract, command)
        .and_then(boost_driver_task_priority_for_bounded_turn);
    (primary, bus_owner)
}

#[cfg(feature = "kernel")]
const fn retained_priority_boost_required(
    physical_pi: bool,
    steady_priority_active: bool,
    steady_priority: usize,
) -> bool {
    physical_pi
        && steady_priority_active
        && steady_priority != 0
        && steady_priority < PI4_BOUNDED_BOOTSTRAP_PRIORITY as usize
}

const DRIVER_TASK_RETAINED_LEASE_PRIMARY: usize = 1 << 0;
const DRIVER_TASK_RETAINED_LEASE_BUS: usize = 1 << 1;

#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum DriverTaskRetainedLeasePhase {
    Inactive,
    BoostBus,
    BoostPrimary,
    ReadyToIssue,
    GrantRequired,
    Granted,
    Committed,
    Issued,
    RestorePrimary,
    RestoreBus,
    ReadyToComplete,
    /// The child may have executed the immutable request, but root lost the
    /// endpoint-wake cursor. The slot remains quarantined until explicit
    /// transport recovery; it must never accept or alias another request.
    Poisoned,
}

#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum DriverTaskRetainedLeaseOperation {
    None,
    BoostBus,
    BoostPrimary,
    CommitRing,
    PublishGrant,
    NotifyRing,
    PollRing,
    RestorePrimary,
    RestoreBus,
    Complete,
}

#[cfg(feature = "kernel")]
impl DriverTaskRetainedLeasePhase {
    const fn as_usize(self) -> usize {
        self as usize
    }

    const fn from_usize(value: usize) -> Option<Self> {
        match value {
            0 => Some(Self::Inactive),
            1 => Some(Self::BoostBus),
            2 => Some(Self::BoostPrimary),
            3 => Some(Self::ReadyToIssue),
            4 => Some(Self::GrantRequired),
            5 => Some(Self::Granted),
            6 => Some(Self::Committed),
            7 => Some(Self::Issued),
            8 => Some(Self::RestorePrimary),
            9 => Some(Self::RestoreBus),
            10 => Some(Self::ReadyToComplete),
            11 => Some(Self::Poisoned),
            _ => None,
        }
    }

    const fn operation(self) -> DriverTaskRetainedLeaseOperation {
        match self {
            Self::Inactive => DriverTaskRetainedLeaseOperation::None,
            Self::BoostBus => DriverTaskRetainedLeaseOperation::BoostBus,
            Self::BoostPrimary => DriverTaskRetainedLeaseOperation::BoostPrimary,
            Self::ReadyToIssue => DriverTaskRetainedLeaseOperation::CommitRing,
            Self::GrantRequired => DriverTaskRetainedLeaseOperation::PublishGrant,
            Self::Granted => DriverTaskRetainedLeaseOperation::NotifyRing,
            Self::Committed => DriverTaskRetainedLeaseOperation::NotifyRing,
            Self::Issued => DriverTaskRetainedLeaseOperation::PollRing,
            Self::RestorePrimary => DriverTaskRetainedLeaseOperation::RestorePrimary,
            Self::RestoreBus => DriverTaskRetainedLeaseOperation::RestoreBus,
            Self::ReadyToComplete => DriverTaskRetainedLeaseOperation::Complete,
            Self::Poisoned => DriverTaskRetainedLeaseOperation::None,
        }
    }

    const fn as_str(self) -> &'static str {
        match self {
            Self::Inactive => "inactive",
            Self::BoostBus => "boost-bus",
            Self::BoostPrimary => "boost-primary",
            Self::ReadyToIssue => "ready-to-issue",
            Self::GrantRequired => "grant-required",
            Self::Granted => "granted",
            Self::Committed => "committed",
            Self::Issued => "issued",
            Self::RestorePrimary => "restore-primary",
            Self::RestoreBus => "restore-bus",
            Self::ReadyToComplete => "ready-to-complete",
            Self::Poisoned => "poisoned",
        }
    }

    const fn after_success(self, mask: usize) -> Self {
        match self {
            Self::BoostBus if mask & DRIVER_TASK_RETAINED_LEASE_PRIMARY != 0 => Self::BoostPrimary,
            Self::BoostBus | Self::BoostPrimary => Self::ReadyToIssue,
            Self::RestorePrimary if mask & DRIVER_TASK_RETAINED_LEASE_BUS != 0 => Self::RestoreBus,
            Self::RestorePrimary | Self::RestoreBus => Self::ReadyToComplete,
            _ => self,
        }
    }
}

#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum DriverTaskRetainedLeaseTurn {
    CommitRing,
    PublishGrant,
    NotifyRing,
    PollRing,
    Pending,
    ReadyToComplete,
    Failed,
}

#[cfg(feature = "kernel")]
fn reset_driver_task_retained_priority_lease_slot(slot: &DriverTaskCommandSlot) {
    slot.retained_priority_lease_phase.store(
        DriverTaskRetainedLeasePhase::Inactive.as_usize(),
        Ordering::Release,
    );
    slot.retained_priority_lease_request
        .store(0, Ordering::Release);
    slot.retained_priority_lease_fingerprint
        .store(0, Ordering::Release);
    slot.retained_priority_lease_generation
        .store(0, Ordering::Release);
    slot.retained_priority_lease_mask
        .store(0, Ordering::Release);
    slot.retained_doorbell_issued.store(0, Ordering::Release);
    slot.retained_grant_id.store(0, Ordering::Release);
}

#[cfg(feature = "kernel")]
fn retained_priority_lease_target_mask(
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
) -> usize {
    if !physical_pi_driver_task_only_owner_state_active() {
        return 0;
    }
    let mut mask = 0usize;
    if driver_task_slot_for_contract(contract).is_some_and(|slot| {
        retained_priority_boost_required(
            true,
            driver_task_steady_priority_is_active(slot),
            slot.steady_priority.load(Ordering::Acquire),
        )
    }) {
        mask |= DRIVER_TASK_RETAINED_LEASE_PRIMARY;
    }
    if driver_task_bounded_turn_bus_owner(contract, command)
        .and_then(driver_task_slot_for_contract)
        .is_some_and(|slot| {
            retained_priority_boost_required(
                true,
                driver_task_steady_priority_is_active(slot),
                slot.steady_priority.load(Ordering::Acquire),
            )
        })
    {
        mask |= DRIVER_TASK_RETAINED_LEASE_BUS;
    }
    mask
}

#[cfg(feature = "kernel")]
fn retained_priority_lease_target(
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
    bus: bool,
) -> Option<(DriverTaskContract, &'static DriverTaskCommandSlot)> {
    let target = if bus {
        driver_task_bounded_turn_bus_owner(contract, command)?
    } else {
        contract
    };
    Some((target, driver_task_slot_for_contract(target)?))
}

#[cfg(feature = "kernel")]
fn set_driver_task_retained_priority(
    _contract: DriverTaskContract,
    slot: &DriverTaskCommandSlot,
    owner_token: usize,
    boost: bool,
) -> bool {
    if slot.retained_priority_boost_active.load(Ordering::Acquire) != owner_token {
        return false;
    }
    let tcb = slot.tcb.load(Ordering::Acquire);
    let priority = if boost {
        PI4_BOUNDED_BOOTSTRAP_PRIORITY
    } else {
        let Ok(priority) = u8::try_from(slot.steady_priority.load(Ordering::Acquire)) else {
            return false;
        };
        if priority == 0 {
            return false;
        }
        priority
    };
    if tcb == 0
        || crate::sel4::set_tcb_sched_params(
            tcb as sel4_sys::seL4_CPtr,
            sel4_sys::seL4_CapInitThreadTCB,
            priority,
            priority,
        )
        .is_err()
    {
        return false;
    }
    true
}

#[cfg(feature = "kernel")]
fn driver_task_retained_lease_generation(contract: DriverTaskContract) -> u32 {
    if driver_task_retained_contract_owns_pair_recovery(contract) {
        CYW43_SDIO_PAIR_RESTART_EPOCH.load(Ordering::Acquire)
    } else {
        // A Wi-Fi pair restart must never invalidate an unrelated serial, USB,
        // display, PCIe, or GENET request. Those services retain their own
        // transport identity until their device-local recovery path resets it.
        0
    }
}

#[cfg(feature = "kernel")]
fn driver_task_retained_uses_root_grant(
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
) -> bool {
    contract == CYW43_WIFI_DRIVER_TASK_CONTRACT && command.aux0 == DRIVER_RUNTIME_CYW43_COMMAND_AUX
}

#[cfg(feature = "kernel")]
fn driver_task_retained_lease_identity_matches(
    slot: &DriverTaskCommandSlot,
    contract: DriverTaskContract,
    request: usize,
    fingerprint: u32,
) -> bool {
    slot.retained_priority_lease_request.load(Ordering::Acquire) == request
        && slot
            .retained_priority_lease_fingerprint
            .load(Ordering::Acquire)
            == fingerprint
        && slot
            .retained_priority_lease_generation
            .load(Ordering::Acquire)
            == driver_task_retained_lease_generation(contract)
}

#[cfg(feature = "kernel")]
fn driver_task_retained_contract_owns_pair_recovery(contract: DriverTaskContract) -> bool {
    contract == CYW43_WIFI_DRIVER_TASK_CONTRACT || contract == SDIO_HOST_DRIVER_TASK_CONTRACT
}

/// Fail one retained scheduling lease without crossing device recovery domains.
///
/// Only issued or scheduler-mutating CYW43/SDIO failures may request pair
/// recovery. A pre-issue failure that has not changed either TCB releases its
/// reservations and clears locally; converting that harmless contention into
/// a full pair restart creates an unbounded recovery amplifier. A non-pair
/// request that crossed the sequence issue boundary remains locally poisoned.
#[cfg(feature = "kernel")]
fn fail_driver_task_retained_priority_lease(
    slot: &DriverTaskCommandSlot,
    contract: DriverTaskContract,
) {
    if slot.retained_doorbell_issued.load(Ordering::Acquire) != 0 {
        if driver_task_retained_contract_owns_pair_recovery(contract) {
            request_cyw43_sdio_pair_restart();
        } else {
            poison_driver_task_retained_request(slot);
        }
        return;
    }
    let phase = DriverTaskRetainedLeasePhase::from_usize(
        slot.retained_priority_lease_phase.load(Ordering::Acquire),
    );
    let mask = slot.retained_priority_lease_mask.load(Ordering::Acquire);
    let scheduler_unchanged = matches!(phase, Some(DriverTaskRetainedLeasePhase::Inactive))
        || matches!(phase, Some(DriverTaskRetainedLeasePhase::BoostBus))
        || (matches!(phase, Some(DriverTaskRetainedLeasePhase::BoostPrimary))
            && mask & DRIVER_TASK_RETAINED_LEASE_BUS == 0)
        || (matches!(phase, Some(DriverTaskRetainedLeasePhase::ReadyToIssue)) && mask == 0);
    if driver_task_retained_contract_owns_pair_recovery(contract) && !scheduler_unchanged {
        request_cyw43_sdio_pair_restart();
        return;
    }
    let owner_token = driver_task_contract_key(contract)
        .map(|task_key| task_key.saturating_add(1))
        .unwrap_or(0);
    let mut reservations_released = owner_token != 0;
    if mask & DRIVER_TASK_RETAINED_LEASE_BUS != 0 {
        let bus_contract = if contract == CYW43_WIFI_DRIVER_TASK_CONTRACT {
            Some(SDIO_HOST_DRIVER_TASK_CONTRACT)
        } else if contract == USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT {
            Some(PCIE_ROOT_DRIVER_TASK_CONTRACT)
        } else {
            None
        };
        reservations_released &= bus_contract
            .and_then(driver_task_slot_for_contract)
            .is_some_and(|bus_slot| {
                bus_slot
                    .retained_priority_boost_active
                    .compare_exchange(owner_token, 0, Ordering::AcqRel, Ordering::Acquire)
                    .is_ok()
            });
    }
    if mask & DRIVER_TASK_RETAINED_LEASE_PRIMARY != 0 {
        reservations_released &= slot
            .retained_priority_boost_active
            .compare_exchange(owner_token, 0, Ordering::AcqRel, Ordering::Acquire)
            .is_ok();
    }
    if !reservations_released && driver_task_retained_contract_owns_pair_recovery(contract) {
        request_cyw43_sdio_pair_restart();
        return;
    }
    slot.active.store(0, Ordering::Release);
    slot.active_command_fingerprint.store(0, Ordering::Release);
    slot.timeout_resumes.store(0, Ordering::Release);
    reset_driver_task_retained_priority_lease_slot(slot);
}

#[cfg(feature = "kernel")]
fn initialize_driver_task_retained_priority_lease(
    slot: &DriverTaskCommandSlot,
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
    request: usize,
    fingerprint: u32,
) -> bool {
    if driver_task_retained_uses_root_grant(contract, command) {
        if !driver_runtime_is_cyw43_root_continuation(command.arg0, command.arg1, command.aux0)
            || slot.root_notification.load(Ordering::Acquire) == 0
        {
            return false;
        }
    }
    let mask = retained_priority_lease_target_mask(contract, command);
    let Some(task_key) = driver_task_contract_key(contract) else {
        return false;
    };
    let owner_token = task_key.saturating_add(1);
    let mut bus_reserved = false;
    if mask & DRIVER_TASK_RETAINED_LEASE_BUS != 0 {
        let Some((_, bus_slot)) = retained_priority_lease_target(contract, command, true) else {
            return false;
        };
        if bus_slot
            .retained_priority_boost_active
            .compare_exchange(0, owner_token, Ordering::AcqRel, Ordering::Acquire)
            .is_err()
        {
            return false;
        }
        bus_reserved = true;
    }
    if mask & DRIVER_TASK_RETAINED_LEASE_PRIMARY != 0
        && slot
            .retained_priority_boost_active
            .compare_exchange(0, owner_token, Ordering::AcqRel, Ordering::Acquire)
            .is_err()
    {
        if bus_reserved {
            if let Some((_, bus_slot)) = retained_priority_lease_target(contract, command, true) {
                let _ = bus_slot.retained_priority_boost_active.compare_exchange(
                    owner_token,
                    0,
                    Ordering::AcqRel,
                    Ordering::Acquire,
                );
            }
        }
        return false;
    }
    slot.retained_priority_lease_request
        .store(request, Ordering::Release);
    slot.retained_priority_lease_fingerprint
        .store(fingerprint, Ordering::Release);
    slot.retained_priority_lease_generation.store(
        driver_task_retained_lease_generation(contract),
        Ordering::Release,
    );
    slot.retained_priority_lease_mask
        .store(mask, Ordering::Release);
    slot.retained_priority_lease_phase.store(
        if mask & DRIVER_TASK_RETAINED_LEASE_BUS != 0 {
            DriverTaskRetainedLeasePhase::BoostBus
        } else if mask & DRIVER_TASK_RETAINED_LEASE_PRIMARY != 0 {
            DriverTaskRetainedLeasePhase::BoostPrimary
        } else {
            DriverTaskRetainedLeasePhase::ReadyToIssue
        }
        .as_usize(),
        Ordering::Release,
    );
    true
}

/// Advance one request-bound retained scheduling lease turn.
///
/// Each `Pending` result performed at most one scheduler syscall. The caller
/// must return to the outer EventPump before asking for the ring send/poll or
/// the next boost/restore step.
#[cfg(feature = "kernel")]
fn step_driver_task_retained_priority_lease(
    slot: &DriverTaskCommandSlot,
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
    request: usize,
    fingerprint: u32,
) -> DriverTaskRetainedLeaseTurn {
    let mut phase = DriverTaskRetainedLeasePhase::from_usize(
        slot.retained_priority_lease_phase.load(Ordering::Acquire),
    );
    if phase == Some(DriverTaskRetainedLeasePhase::Inactive) {
        if !initialize_driver_task_retained_priority_lease(
            slot,
            contract,
            command,
            request,
            fingerprint,
        ) {
            fail_driver_task_retained_priority_lease(slot, contract);
            return DriverTaskRetainedLeaseTurn::Failed;
        }
        phase = DriverTaskRetainedLeasePhase::from_usize(
            slot.retained_priority_lease_phase.load(Ordering::Acquire),
        );
        if phase == Some(DriverTaskRetainedLeasePhase::Inactive) {
            fail_driver_task_retained_priority_lease(slot, contract);
            return DriverTaskRetainedLeaseTurn::Failed;
        }
    }
    if phase == Some(DriverTaskRetainedLeasePhase::Poisoned) {
        return DriverTaskRetainedLeaseTurn::Failed;
    }
    if !driver_task_retained_lease_identity_matches(slot, contract, request, fingerprint) {
        fail_driver_task_retained_priority_lease(slot, contract);
        return DriverTaskRetainedLeaseTurn::Failed;
    }
    let mask = slot.retained_priority_lease_mask.load(Ordering::Acquire);
    let Some(task_key) = driver_task_contract_key(contract) else {
        fail_driver_task_retained_priority_lease(slot, contract);
        return DriverTaskRetainedLeaseTurn::Failed;
    };
    let owner_token = task_key.saturating_add(1);
    if mask & DRIVER_TASK_RETAINED_LEASE_PRIMARY != 0
        && slot.retained_priority_boost_active.load(Ordering::Acquire) != owner_token
    {
        fail_driver_task_retained_priority_lease(slot, contract);
        return DriverTaskRetainedLeaseTurn::Failed;
    }
    if mask & DRIVER_TASK_RETAINED_LEASE_BUS != 0
        && !retained_priority_lease_target(contract, command, true).is_some_and(|(_, bus_slot)| {
            bus_slot
                .retained_priority_boost_active
                .load(Ordering::Acquire)
                == owner_token
        })
    {
        fail_driver_task_retained_priority_lease(slot, contract);
        return DriverTaskRetainedLeaseTurn::Failed;
    }
    let Some(phase) = phase else {
        fail_driver_task_retained_priority_lease(slot, contract);
        return DriverTaskRetainedLeaseTurn::Failed;
    };
    let doorbell_issued = slot.retained_doorbell_issued.load(Ordering::Acquire) != 0;
    let doorbell_state_valid = match phase {
        DriverTaskRetainedLeasePhase::BoostBus
        | DriverTaskRetainedLeasePhase::BoostPrimary
        | DriverTaskRetainedLeasePhase::ReadyToIssue => !doorbell_issued,
        DriverTaskRetainedLeasePhase::GrantRequired
        | DriverTaskRetainedLeasePhase::Granted
        | DriverTaskRetainedLeasePhase::Committed
        | DriverTaskRetainedLeasePhase::Issued
        | DriverTaskRetainedLeasePhase::RestorePrimary
        | DriverTaskRetainedLeasePhase::RestoreBus
        | DriverTaskRetainedLeasePhase::ReadyToComplete
        | DriverTaskRetainedLeasePhase::Poisoned => doorbell_issued,
        DriverTaskRetainedLeasePhase::Inactive => false,
    };
    if !doorbell_state_valid {
        fail_driver_task_retained_priority_lease(slot, contract);
        return DriverTaskRetainedLeaseTurn::Failed;
    }
    let result = match phase.operation() {
        DriverTaskRetainedLeaseOperation::BoostBus => {
            let Some((target, target_slot)) =
                retained_priority_lease_target(contract, command, true)
            else {
                fail_driver_task_retained_priority_lease(slot, contract);
                return DriverTaskRetainedLeaseTurn::Failed;
            };
            if !set_driver_task_retained_priority(target, target_slot, owner_token, true) {
                fail_driver_task_retained_priority_lease(slot, contract);
                return DriverTaskRetainedLeaseTurn::Failed;
            }
            let next = phase.after_success(mask);
            slot.retained_priority_lease_phase
                .store(next.as_usize(), Ordering::Release);
            DriverTaskRetainedLeaseTurn::Pending
        }
        DriverTaskRetainedLeaseOperation::BoostPrimary => {
            let Some((target, target_slot)) =
                retained_priority_lease_target(contract, command, false)
            else {
                fail_driver_task_retained_priority_lease(slot, contract);
                return DriverTaskRetainedLeaseTurn::Failed;
            };
            if !set_driver_task_retained_priority(target, target_slot, owner_token, true) {
                fail_driver_task_retained_priority_lease(slot, contract);
                return DriverTaskRetainedLeaseTurn::Failed;
            }
            slot.retained_priority_lease_phase
                .store(phase.after_success(mask).as_usize(), Ordering::Release);
            DriverTaskRetainedLeaseTurn::Pending
        }
        DriverTaskRetainedLeaseOperation::CommitRing => DriverTaskRetainedLeaseTurn::CommitRing,
        DriverTaskRetainedLeaseOperation::PublishGrant => DriverTaskRetainedLeaseTurn::PublishGrant,
        DriverTaskRetainedLeaseOperation::NotifyRing => DriverTaskRetainedLeaseTurn::NotifyRing,
        DriverTaskRetainedLeaseOperation::PollRing => DriverTaskRetainedLeaseTurn::PollRing,
        DriverTaskRetainedLeaseOperation::RestorePrimary => {
            let Some((target, target_slot)) =
                retained_priority_lease_target(contract, command, false)
            else {
                fail_driver_task_retained_priority_lease(slot, contract);
                return DriverTaskRetainedLeaseTurn::Failed;
            };
            if !set_driver_task_retained_priority(target, target_slot, owner_token, false) {
                fail_driver_task_retained_priority_lease(slot, contract);
                return DriverTaskRetainedLeaseTurn::Failed;
            }
            let next = phase.after_success(mask);
            slot.retained_priority_lease_phase
                .store(next.as_usize(), Ordering::Release);
            DriverTaskRetainedLeaseTurn::Pending
        }
        DriverTaskRetainedLeaseOperation::RestoreBus => {
            let Some((target, target_slot)) =
                retained_priority_lease_target(contract, command, true)
            else {
                fail_driver_task_retained_priority_lease(slot, contract);
                return DriverTaskRetainedLeaseTurn::Failed;
            };
            if !set_driver_task_retained_priority(target, target_slot, owner_token, false) {
                fail_driver_task_retained_priority_lease(slot, contract);
                return DriverTaskRetainedLeaseTurn::Failed;
            }
            slot.retained_priority_lease_phase
                .store(phase.after_success(mask).as_usize(), Ordering::Release);
            DriverTaskRetainedLeaseTurn::Pending
        }
        DriverTaskRetainedLeaseOperation::Complete => DriverTaskRetainedLeaseTurn::ReadyToComplete,
        DriverTaskRetainedLeaseOperation::None => DriverTaskRetainedLeaseTurn::Failed,
    };
    if result == DriverTaskRetainedLeaseTurn::Failed {
        fail_driver_task_retained_priority_lease(slot, contract);
    }
    result
}

#[cfg(feature = "kernel")]
fn mark_driver_task_retained_priority_lease_committed(
    slot: &DriverTaskCommandSlot,
    root_grant: bool,
) -> bool {
    slot.retained_priority_lease_phase
        .compare_exchange(
            DriverTaskRetainedLeasePhase::ReadyToIssue.as_usize(),
            if root_grant {
                DriverTaskRetainedLeasePhase::GrantRequired
            } else {
                DriverTaskRetainedLeasePhase::Committed
            }
            .as_usize(),
            Ordering::AcqRel,
            Ordering::Acquire,
        )
        .is_ok()
}

#[cfg(feature = "kernel")]
fn mark_driver_task_retained_priority_lease_granted(slot: &DriverTaskCommandSlot) -> bool {
    slot.retained_priority_lease_phase
        .compare_exchange(
            DriverTaskRetainedLeasePhase::GrantRequired.as_usize(),
            DriverTaskRetainedLeasePhase::Granted.as_usize(),
            Ordering::AcqRel,
            Ordering::Acquire,
        )
        .is_ok()
}

#[cfg(feature = "kernel")]
const fn next_driver_task_retained_grant_id(current: u32) -> Option<u32> {
    match current.checked_add(1) {
        Some(next) if next != 0 => Some(next),
        Some(_) | None => None,
    }
}

#[cfg(feature = "kernel")]
fn mark_driver_task_retained_priority_lease_issued(
    slot: &DriverTaskCommandSlot,
    root_grant: bool,
) -> bool {
    slot.retained_priority_lease_phase
        .compare_exchange(
            if root_grant {
                DriverTaskRetainedLeasePhase::Granted
            } else {
                DriverTaskRetainedLeasePhase::Committed
            }
            .as_usize(),
            DriverTaskRetainedLeasePhase::Issued.as_usize(),
            Ordering::AcqRel,
            Ordering::Acquire,
        )
        .is_ok()
}

#[cfg(feature = "kernel")]
fn driver_task_continuation_grant_matches(
    grant: DriverRuntimeContinuationGrant,
    command: DriverTaskCommandRecord,
    grant_id: u32,
) -> bool {
    grant.magic == DRIVER_RUNTIME_CONTINUATION_GRANT_MAGIC
        && grant.request_sequence == command.sequence
        && grant.action_fingerprint == driver_task_runtime_continuation_fingerprint(command)
        && grant.generation == command.aux1
        && grant.grant_id == grant_id
        && grant_id != 0
        && (grant.consumed_grant_id == 0 || grant.consumed_grant_id == grant_id)
}

/// Re-arm one immutable retained continuation after a completion poll miss.
///
/// Every CYW43 descriptor turn uses a durable exact grant plus the root-badged
/// notification. A still-pending grant is merely re-signalled; a consumed
/// grant schedules publication of the next monotonic ticket. Other runtime
/// contracts retain their endpoint rendezvous.
#[cfg(feature = "kernel")]
fn arm_driver_task_retained_priority_lease_wake_retry(
    slot: &DriverTaskCommandSlot,
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
    ring_root_ptr: usize,
    request: usize,
    fingerprint: u32,
) -> bool {
    if !driver_task_retained_lease_identity_matches(slot, contract, request, fingerprint)
        || slot.retained_doorbell_issued.load(Ordering::Acquire) == 0
    {
        return false;
    }
    let next = if driver_task_retained_uses_root_grant(contract, command) {
        let grant_id = slot.retained_grant_id.load(Ordering::Acquire);
        let Some(grant) = driver_task_ring_read_continuation_grant(ring_root_ptr) else {
            return false;
        };
        if !driver_task_continuation_grant_matches(grant, command, grant_id) {
            return false;
        }
        if grant.consumed_grant_id == grant_id {
            DriverTaskRetainedLeasePhase::GrantRequired
        } else {
            DriverTaskRetainedLeasePhase::Granted
        }
    } else {
        DriverTaskRetainedLeasePhase::Committed
    };
    slot.retained_priority_lease_phase
        .compare_exchange(
            DriverTaskRetainedLeasePhase::Issued.as_usize(),
            next.as_usize(),
            Ordering::AcqRel,
            Ordering::Acquire,
        )
        .is_ok()
}

/// Quarantine an issued retained request whose wake cursor could not advance.
///
/// This deliberately preserves `active`, the request sequence, immutable
/// fingerprint, and issued latch. A late child action or completion therefore
/// remains bound to the poisoned slot and can never be mistaken for a fresh
/// request. Only explicit transport recovery may reset the lease.
#[cfg(feature = "kernel")]
fn poison_driver_task_retained_request(slot: &DriverTaskCommandSlot) {
    slot.retained_priority_lease_phase.store(
        DriverTaskRetainedLeasePhase::Poisoned.as_usize(),
        Ordering::Release,
    );
    // Preserve any existing identity fields and force the slot closed even if
    // the detected tear included `active`. Recovery, not ordinary submission,
    // is the only authority allowed to reopen this issued-unknown transport.
    slot.active.store(1, Ordering::Release);
}

#[cfg(feature = "kernel")]
fn latch_driver_task_retained_priority_lease_completion(
    slot: &DriverTaskCommandSlot,
) -> DriverTaskRetainedLeaseTurn {
    let Some(phase) = DriverTaskRetainedLeasePhase::from_usize(
        slot.retained_priority_lease_phase.load(Ordering::Acquire),
    ) else {
        return DriverTaskRetainedLeaseTurn::Failed;
    };
    if phase != DriverTaskRetainedLeasePhase::Issued
        || slot.retained_doorbell_issued.load(Ordering::Acquire) == 0
    {
        return DriverTaskRetainedLeaseTurn::Failed;
    }
    let mask = slot.retained_priority_lease_mask.load(Ordering::Acquire);
    let next = if mask & DRIVER_TASK_RETAINED_LEASE_PRIMARY != 0 {
        DriverTaskRetainedLeasePhase::RestorePrimary
    } else if mask & DRIVER_TASK_RETAINED_LEASE_BUS != 0 {
        DriverTaskRetainedLeasePhase::RestoreBus
    } else {
        DriverTaskRetainedLeasePhase::ReadyToComplete
    };
    slot.retained_priority_lease_phase
        .store(next.as_usize(), Ordering::Release);
    if next == DriverTaskRetainedLeasePhase::ReadyToComplete {
        DriverTaskRetainedLeaseTurn::ReadyToComplete
    } else {
        DriverTaskRetainedLeaseTurn::Pending
    }
}

#[cfg(feature = "kernel")]
fn finish_driver_task_retained_priority_lease(
    slot: &DriverTaskCommandSlot,
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
    request: usize,
    fingerprint: u32,
) -> bool {
    if !driver_task_retained_lease_identity_matches(slot, contract, request, fingerprint)
        || DriverTaskRetainedLeasePhase::from_usize(
            slot.retained_priority_lease_phase.load(Ordering::Acquire),
        ) != Some(DriverTaskRetainedLeasePhase::ReadyToComplete)
    {
        return false;
    }
    let Some(task_key) = driver_task_contract_key(contract) else {
        return false;
    };
    let owner_token = task_key.saturating_add(1);
    let mask = slot.retained_priority_lease_mask.load(Ordering::Acquire);
    if mask & DRIVER_TASK_RETAINED_LEASE_BUS != 0 {
        let Some((_, bus_slot)) = retained_priority_lease_target(contract, command, true) else {
            return false;
        };
        if bus_slot
            .retained_priority_boost_active
            .compare_exchange(owner_token, 0, Ordering::AcqRel, Ordering::Acquire)
            .is_err()
        {
            return false;
        }
    }
    if mask & DRIVER_TASK_RETAINED_LEASE_PRIMARY != 0
        && slot
            .retained_priority_boost_active
            .compare_exchange(owner_token, 0, Ordering::AcqRel, Ordering::Acquire)
            .is_err()
    {
        return false;
    }
    reset_driver_task_retained_priority_lease_slot(slot);
    true
}

#[cfg(feature = "kernel")]
fn register_driver_task_ring_service_with_kind(
    contract: DriverTaskContract,
    context: usize,
    handler: DriverTaskRingServiceHandler,
    kind: DriverTaskRingServiceKind,
) -> bool {
    let Some(task_key) = driver_task_contract_key(contract) else {
        return false;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return false;
    };
    slot.ring_context.store(context, Ordering::Release);
    slot.ring_handler
        .store(handler as *const () as usize, Ordering::Release);
    slot.ring_service_kind
        .store(kind.as_usize(), Ordering::Release);
    true
}

/// Register a transitional shared-ring handler that receives root context.
///
/// This keeps the physical Pi 4 service path explicit while the live hardware
/// state still resides in root-owned structs. Commands submitted through this
/// registration are forced into root-context non-acceptance and cannot satisfy
/// owner-state proof.
#[cfg(feature = "kernel")]
pub fn register_driver_task_root_context_ring_service(
    contract: DriverTaskContract,
    context: usize,
    handler: DriverTaskRingServiceHandler,
) -> bool {
    register_driver_task_ring_service_with_kind(
        contract,
        context,
        handler,
        DriverTaskRingServiceKind::RootContextDiagnostic,
    )
}

/// Register a pointer-free shared-ring handler.
///
/// The context word must be a primitive selector, not a root pointer. This
/// class is necessary but not sufficient for owner-state proof; proof is still
/// gated by isolated VSpace, pointer-free IPC, and per-hot-path owner-state
/// descriptors.
#[cfg(feature = "kernel")]
pub fn register_driver_task_pointer_free_ring_service(
    contract: DriverTaskContract,
    selector: usize,
    handler: DriverTaskRingServiceHandler,
) -> bool {
    register_driver_task_ring_service_with_kind(
        contract,
        selector,
        handler,
        DriverTaskRingServiceKind::PointerFreeSelector,
    )
}

#[cfg(feature = "kernel")]
fn driver_task_ring_service_kind(contract: DriverTaskContract) -> DriverTaskRingServiceKind {
    let Some(task_key) = driver_task_contract_key(contract) else {
        return DriverTaskRingServiceKind::None;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return DriverTaskRingServiceKind::None;
    };
    DriverTaskRingServiceKind::from_usize(slot.ring_service_kind.load(Ordering::Acquire))
}

/// Returns whether a completed ring service may credit owner-state proof.
#[must_use]
pub const fn driver_task_ring_service_owner_state_credit_eligible(
    kind: DriverTaskRingServiceKind,
    command: DriverTaskCommandRecord,
) -> bool {
    kind.owner_state_credit_allowed() && command.owner_state_credit_eligible()
}

/// Pointer-free descriptor proving a hardware owner's state boundary.
///
/// The descriptor is intentionally primitive-only. It identifies the ring-backed
/// hardware owner and the bounded shared-buffer region used to exchange work
/// with root, but it never carries a root pointer or callback context.
#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct DriverTaskOwnerStateDescriptor {
    /// Hot path owned by the driver task.
    pub hot_path: DriverTaskHotPath,
    /// Offset of the command/metadata region within the shared ring page.
    pub state_offset: u32,
    /// Bytes reserved for driver-owned state metadata.
    pub state_len: u16,
    /// Offset of the shared RX/TX/control buffer region.
    pub buffer_offset: u32,
    /// Bytes reserved for shared buffers.
    pub buffer_len: u16,
    /// Descriptor flags reserved for future ownership variants.
    pub flags: u16,
}

impl DriverTaskOwnerStateDescriptor {
    /// Construct a bounded owner-state descriptor.
    #[must_use]
    pub const fn new(
        hot_path: DriverTaskHotPath,
        state_offset: u32,
        state_len: u16,
        buffer_offset: u32,
        buffer_len: u16,
        flags: u16,
    ) -> Option<Self> {
        let state_end = state_offset as usize + state_len as usize;
        let buffer_end = buffer_offset as usize + buffer_len as usize;
        let state_in_owner_region = (state_offset as usize) >= DRIVER_TASK_OWNER_STATE_OFFSET
            && state_end <= DRIVER_TASK_OWNER_STATE_OFFSET + DRIVER_TASK_OWNER_STATE_BYTES;
        if state_len == 0
            || buffer_len == 0
            || state_offset as usize >= DRIVER_TASK_RING_PAGE_BYTES
            || buffer_offset as usize >= DRIVER_TASK_RING_PAGE_BYTES
            || state_end > DRIVER_TASK_RING_PAGE_BYTES
            || buffer_end > DRIVER_TASK_RING_PAGE_BYTES
            || !state_in_owner_region
            || (buffer_offset as usize) < DRIVER_TASK_RING_FRAME_OFFSET
        {
            return None;
        }
        Some(Self {
            hot_path,
            state_offset,
            state_len,
            buffer_offset,
            buffer_len,
            flags,
        })
    }

    /// Returns whether this descriptor represents a real isolated runtime
    /// ownership boundary rather than ring-shape scaffolding.
    #[must_use]
    pub const fn has_required_runtime_flags(self) -> bool {
        self.flags & DRIVER_TASK_OWNER_STATE_REQUIRED_FLAGS
            == DRIVER_TASK_OWNER_STATE_REQUIRED_FLAGS
    }
}

/// Register pointer-free owner-state proof for one driver-task hot path.
#[cfg(feature = "kernel")]
pub fn register_driver_task_owner_state_descriptor(
    contract: DriverTaskContract,
    descriptor: DriverTaskOwnerStateDescriptor,
) -> bool {
    if descriptor.hot_path.contract() != contract {
        return false;
    }
    if !descriptor.has_required_runtime_flags() {
        return false;
    }
    let Some(spec) = pi4_driver_task_runtime_image_spec_for_contract(contract) else {
        return false;
    };
    if spec.hot_path != descriptor.hot_path || !spec.acceptance_eligible() {
        return false;
    }
    let role_bit = driver_task_role_bit(contract.kind);
    if role_bit == 0 {
        return false;
    }
    DRIVER_TASK_OWNER_STATE_ROLE_MASK.fetch_or(role_bit, Ordering::AcqRel);
    DRIVER_TASK_OWNER_STATE_HOT_PATH_MASK
        .fetch_or(descriptor.hot_path.owner_state_bit(), Ordering::AcqRel);
    DRIVER_TASK_SHARED_RING_SERVICE_ROLE_MASK.fetch_or(role_bit, Ordering::AcqRel);
    DRIVER_TASK_HOT_PATH_ROLE_MASK.fetch_or(role_bit, Ordering::AcqRel);
    refresh_driver_task_owner_state_proof();
    true
}

/// Register the standard linked-runtime owner-state descriptor after hardware progress.
#[cfg(feature = "kernel")]
pub fn register_driver_task_runtime_owner_state(hot_path: DriverTaskHotPath) -> bool {
    let Some(descriptor) = DriverTaskOwnerStateDescriptor::new(
        hot_path,
        DRIVER_TASK_OWNER_STATE_OFFSET as u32,
        DRIVER_TASK_OWNER_STATE_METADATA_BYTES,
        DRIVER_TASK_RING_FRAME_OFFSET as u32,
        MAX_DRIVER_TASK_FRAME_BYTES as u16,
        DRIVER_TASK_OWNER_STATE_REQUIRED_FLAGS,
    ) else {
        return false;
    };
    register_driver_task_owner_state_descriptor(hot_path.contract(), descriptor)
}

/// Return whether one runtime hot path has registered pointer-free owner state.
#[cfg(feature = "kernel")]
#[must_use]
pub fn driver_task_runtime_owner_state_registered(hot_path: DriverTaskHotPath) -> bool {
    DRIVER_TASK_OWNER_STATE_HOT_PATH_MASK.load(Ordering::Acquire) & hot_path.owner_state_bit() != 0
}

/// Re-emit the canonical boot contract after a Pi 4 owner-state transition.
#[cfg(feature = "kernel")]
pub fn emit_owner_state_transition_boot_contract_proof(hot_path: DriverTaskHotPath) {
    if physical_pi_driver_task_only_owner_state_active()
        && driver_task_runtime_owner_state_registered(hot_path)
    {
        emit_boot_contract_proof();
    }
}

#[cfg(feature = "kernel")]
fn refresh_driver_task_owner_state_proof() {
    let owner_hot_paths = DRIVER_TASK_OWNER_STATE_HOT_PATH_MASK.load(Ordering::Acquire);
    let required_hot_paths = current_pi4_acceptance_hot_path_mask();
    let ready = owner_hot_paths & required_hot_paths == required_hot_paths
        && DRIVER_TASK_VSPACE_PROOF.load(Ordering::Acquire) != 0
        && DRIVER_TASK_POINTER_FREE_IPC_PROOF.load(Ordering::Acquire) != 0;
    DRIVER_TASK_OWNER_STATE_PROOF.store(ready as usize, Ordering::Release);
}

/// Register the pointer-free default service handler for Pi 4 bus owner roles.
#[cfg(feature = "kernel")]
pub fn register_pi4_bus_ring_service(contract: DriverTaskContract) -> bool {
    let hot_path = if contract == SDIO_HOST_DRIVER_TASK_CONTRACT {
        DriverTaskHotPath::SdioHost
    } else if contract == PCIE_ROOT_DRIVER_TASK_CONTRACT {
        DriverTaskHotPath::PcieRoot
    } else {
        return false;
    };
    register_driver_task_pointer_free_ring_service(
        contract,
        hot_path.as_u32() as usize,
        pi4_bus_ring_service_driver_task,
    )
}

/// Stage a bounded payload into the driver-task ring shared-buffer area.
#[cfg(feature = "kernel")]
pub fn stage_driver_task_ring_frame(
    contract: DriverTaskContract,
    payload: &[u8],
    flags: u16,
) -> Option<DriverFrameDescriptor> {
    stage_driver_task_ring_payload_at(contract, DRIVER_TASK_RING_FRAME_OFFSET, payload, flags)
}

/// A caller-provided payload segment copied only after the HAL owns the ring slot.
#[cfg(feature = "kernel")]
#[derive(Clone, Copy)]
pub enum DriverTaskStagingSegment<'a> {
    /// Bytes copied into the command ring page.
    Ring {
        /// Runtime-visible offset in the ring page.
        offset: usize,
        /// Bytes to stage.
        payload: &'a [u8],
        /// Descriptor flags for the staged bytes.
        flags: u16,
    },
    /// Bytes copied into the bus-link shared payload window.
    Shared {
        /// Bytes to stage.
        payload: &'a [u8],
        /// Descriptor flags for the staged bytes.
        flags: u16,
    },
}

#[cfg(feature = "kernel")]
impl<'a> DriverTaskStagingSegment<'a> {
    /// Construct a ring-frame segment at the canonical frame offset.
    pub const fn ring_frame(payload: &'a [u8], flags: u16) -> Self {
        Self::Ring {
            offset: DRIVER_TASK_RING_FRAME_OFFSET,
            payload,
            flags,
        }
    }

    /// Construct a ring segment at a caller-selected frame offset.
    pub const fn ring_payload_at(offset: usize, payload: &'a [u8], flags: u16) -> Self {
        Self::Ring {
            offset,
            payload,
            flags,
        }
    }

    /// Construct a bus-link shared-payload segment.
    pub const fn shared(payload: &'a [u8], flags: u16) -> Self {
        Self::Shared { payload, flags }
    }
}

/// Describe a canonical ring-frame segment without copying bytes.
#[cfg(feature = "kernel")]
pub fn describe_driver_task_ring_frame(
    payload: &[u8],
    flags: u16,
) -> Option<DriverFrameDescriptor> {
    describe_driver_task_ring_payload_at(DRIVER_TASK_RING_FRAME_OFFSET, payload, flags)
}

/// Describe a ring-page segment without copying bytes.
#[cfg(feature = "kernel")]
pub fn describe_driver_task_ring_payload_at(
    offset: usize,
    payload: &[u8],
    flags: u16,
) -> Option<DriverFrameDescriptor> {
    if payload.len() > MAX_DRIVER_TASK_FRAME_BYTES {
        return None;
    }
    let end = offset.checked_add(payload.len())?;
    if offset < DRIVER_TASK_RING_FRAME_OFFSET || end > DRIVER_TASK_RING_PAGE_BYTES {
        return None;
    }
    DriverFrameDescriptor::new(offset as u32, payload.len() as u16, flags).ok()
}

#[cfg(feature = "kernel")]
fn driver_task_ring_payload_matches(ring_root_ptr: usize, offset: usize, payload: &[u8]) -> bool {
    driver_task_shared_load_barrier();
    let src = (ring_root_ptr + offset) as *const u8;
    for (index, expected) in payload.iter().copied().enumerate() {
        // SAFETY: Callers validate that the payload range lies inside the shared
        // ring page before comparing an active in-flight frame.
        let actual = unsafe { core::ptr::read_volatile(src.add(index)) };
        if actual != expected {
            return false;
        }
    }
    true
}

#[cfg(feature = "kernel")]
fn driver_task_copy_ring_payload(
    slot: &DriverTaskCommandSlot,
    ring_root_ptr: usize,
    offset: usize,
    payload: &[u8],
) {
    let dst = (ring_root_ptr + offset) as *mut u8;
    // SAFETY: Callers validate that the destination lies in the HAL-owned ring
    // page after the fixed records. The submit path calls this only while it
    // owns the per-contract active slot.
    unsafe {
        core::ptr::copy_nonoverlapping(payload.as_ptr(), dst, payload.len());
    }
    driver_task_ring_clean_root_range(dst as usize, payload.len());
    driver_task_record_cache_clean(slot, payload.len());
    driver_task_shared_store_barrier();
}

/// Stage a pointer-free payload at a specific offset in the shared ring page.
#[cfg(feature = "kernel")]
pub fn stage_driver_task_ring_payload_at(
    contract: DriverTaskContract,
    offset: usize,
    payload: &[u8],
    flags: u16,
) -> Option<DriverFrameDescriptor> {
    if payload.len() > MAX_DRIVER_TASK_FRAME_BYTES {
        return None;
    }
    let task_key = driver_task_contract_key(contract)?;
    let slot = slot_for_task_key(task_key)?;
    let _root_producer_guard = acquire_root_ring_producer(contract, slot)?;
    let ring_root_ptr = slot.ring_root_ptr.load(Ordering::Acquire);
    if ring_root_ptr == 0 {
        return None;
    }
    let descriptor = describe_driver_task_ring_payload_at(offset, payload, flags)?;
    if slot.active.load(Ordering::Acquire) != 0 {
        if !driver_task_ring_payload_matches(ring_root_ptr, offset, payload) {
            return None;
        }
        return Some(descriptor);
    }
    driver_task_copy_ring_payload(slot, ring_root_ptr, offset, payload);
    Some(descriptor)
}

/// Payload staged into the fixed driver shared-buffer window.
#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct DriverTaskStagedSharedPayload {
    /// Runtime-visible offset of the first staged byte.
    pub offset: u16,
    /// Number of staged bytes.
    pub len: u16,
    /// Frame flags associated with this payload.
    pub flags: u16,
}

/// Describe a shared-payload segment without copying bytes.
#[cfg(feature = "kernel")]
pub fn describe_driver_task_shared_payload(
    payload: &[u8],
    flags: u16,
) -> Option<DriverTaskStagedSharedPayload> {
    if payload.is_empty() || payload.len() > DRIVER_TASK_SDIO_BUS_SHARED_DATA_BYTES {
        return None;
    }
    Some(DriverTaskStagedSharedPayload {
        offset: DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE,
        len: payload.len() as u16,
        flags,
    })
}

#[cfg(feature = "kernel")]
fn driver_task_required_shared_pages(payload_len: usize) -> Option<usize> {
    if payload_len == 0 || payload_len > DRIVER_TASK_SDIO_BUS_SHARED_DATA_BYTES {
        return None;
    }
    let page_bytes = DRIVER_TASK_RING_PAGE_BYTES;
    let required_pages = payload_len.saturating_add(page_bytes - 1) / page_bytes;
    if required_pages == 0 || required_pages > DRIVER_TASK_BUS_LINK_SHARED_FRAME_CAPACITY {
        return None;
    }
    Some(required_pages)
}

#[cfg(feature = "kernel")]
fn driver_task_shared_payload_pages_ready(
    slot: &DriverTaskCommandSlot,
    payload_len: usize,
) -> bool {
    let Some(required_pages) = driver_task_required_shared_pages(payload_len) else {
        return false;
    };
    if slot.shared_frame_count.load(Ordering::Acquire) < required_pages {
        return false;
    }
    for page in 0..required_pages {
        if slot.shared_frame_root_ptrs[page].load(Ordering::Acquire) == 0 {
            return false;
        }
    }
    true
}

#[cfg(feature = "kernel")]
fn driver_task_shared_payload_matches(slot: &DriverTaskCommandSlot, payload: &[u8]) -> bool {
    let Some(required_pages) = driver_task_required_shared_pages(payload.len()) else {
        return false;
    };
    if slot.shared_frame_count.load(Ordering::Acquire) < required_pages {
        return false;
    }
    let page_bytes = DRIVER_TASK_RING_PAGE_BYTES;
    let mut checked = 0usize;
    driver_task_shared_load_barrier();
    while checked < payload.len() {
        let page = checked / page_bytes;
        let page_offset = checked % page_bytes;
        let root_ptr = slot.shared_frame_root_ptrs[page].load(Ordering::Acquire);
        if root_ptr == 0 {
            return false;
        }
        let chunk = (page_bytes - page_offset).min(payload.len() - checked);
        let src = (root_ptr + page_offset) as *const u8;
        for index in 0..chunk {
            // SAFETY: The root pointer is a HAL-published shared page mapping,
            // and bounds above keep the comparison inside the declared window.
            let actual = unsafe { core::ptr::read_volatile(src.add(index)) };
            if actual != payload[checked + index] {
                return false;
            }
        }
        checked = checked.saturating_add(chunk);
    }
    true
}

#[cfg(feature = "kernel")]
fn driver_task_copy_shared_payload(slot: &DriverTaskCommandSlot, payload: &[u8]) -> Option<()> {
    let required_pages = driver_task_required_shared_pages(payload.len())?;
    if slot.shared_frame_count.load(Ordering::Acquire) < required_pages {
        return None;
    }
    let page_bytes = DRIVER_TASK_RING_PAGE_BYTES;
    let mut copied = 0usize;
    while copied < payload.len() {
        let page = copied / page_bytes;
        let page_offset = copied % page_bytes;
        let root_ptr = slot.shared_frame_root_ptrs[page].load(Ordering::Acquire);
        if root_ptr == 0 {
            return None;
        }
        let chunk = (page_bytes - page_offset).min(payload.len() - copied);
        let dst = root_ptr.checked_add(page_offset)? as *mut u8;
        // SAFETY: The destination is a HAL-published root mapping for one of
        // the fixed shared-buffer pages. The submit path calls this only while
        // it owns the per-contract active slot.
        unsafe {
            core::ptr::copy_nonoverlapping(payload.as_ptr().add(copied), dst, chunk);
        }
        driver_task_shared_store_barrier();
        copied = copied.saturating_add(chunk);
    }
    driver_task_shared_store_barrier();
    Some(())
}

/// Stage a bounded payload into the driver-task shared-buffer pages.
#[cfg(feature = "kernel")]
pub fn stage_driver_task_shared_payload(
    contract: DriverTaskContract,
    payload: &[u8],
    flags: u16,
) -> Option<DriverTaskStagedSharedPayload> {
    let task_key = driver_task_contract_key(contract)?;
    let slot = slot_for_task_key(task_key)?;
    let _root_producer_guard = acquire_root_ring_producer(contract, slot)?;
    let descriptor = describe_driver_task_shared_payload(payload, flags)?;
    if !driver_task_shared_payload_pages_ready(slot, payload.len()) {
        return None;
    }
    if slot.active.load(Ordering::Acquire) != 0 {
        if !driver_task_shared_payload_matches(slot, payload) {
            return None;
        }
        return Some(descriptor);
    }
    driver_task_copy_shared_payload(slot, payload)?;
    Some(descriptor)
}

#[cfg(feature = "kernel")]
fn driver_task_staging_segment_valid(
    slot: &DriverTaskCommandSlot,
    ring_root_ptr: usize,
    segment: DriverTaskStagingSegment<'_>,
) -> bool {
    match segment {
        DriverTaskStagingSegment::Ring {
            offset,
            payload,
            flags,
        } => {
            ring_root_ptr != 0
                && describe_driver_task_ring_payload_at(offset, payload, flags).is_some()
        }
        DriverTaskStagingSegment::Shared { payload, flags } => {
            describe_driver_task_shared_payload(payload, flags).is_some()
                && driver_task_shared_payload_pages_ready(slot, payload.len())
        }
    }
}

#[cfg(feature = "kernel")]
fn driver_task_staging_segments_valid(
    slot: &DriverTaskCommandSlot,
    ring_root_ptr: usize,
    segments: &[DriverTaskStagingSegment<'_>],
) -> bool {
    segments
        .iter()
        .copied()
        .all(|segment| driver_task_staging_segment_valid(slot, ring_root_ptr, segment))
}

#[cfg(feature = "kernel")]
fn driver_task_stage_segment(
    slot: &DriverTaskCommandSlot,
    ring_root_ptr: usize,
    segment: DriverTaskStagingSegment<'_>,
) -> Option<()> {
    match segment {
        DriverTaskStagingSegment::Ring {
            offset,
            payload,
            flags,
        } => {
            let _ = describe_driver_task_ring_payload_at(offset, payload, flags)?;
            driver_task_copy_ring_payload(slot, ring_root_ptr, offset, payload);
            Some(())
        }
        DriverTaskStagingSegment::Shared { payload, flags } => {
            let _ = describe_driver_task_shared_payload(payload, flags)?;
            driver_task_copy_shared_payload(slot, payload)
        }
    }
}

#[cfg(feature = "kernel")]
fn driver_task_stage_segments(
    slot: &DriverTaskCommandSlot,
    ring_root_ptr: usize,
    segments: &[DriverTaskStagingSegment<'_>],
) -> Option<()> {
    if !driver_task_staging_segments_valid(slot, ring_root_ptr, segments) {
        return None;
    }
    for segment in segments.iter().copied() {
        driver_task_stage_segment(slot, ring_root_ptr, segment)?;
    }
    Some(())
}

/// Stage a pointer-free runtime initialization descriptor into the shared ring.
#[cfg(feature = "kernel")]
pub fn stage_driver_runtime_init_descriptor(
    contract: DriverTaskContract,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Option<DriverFrameDescriptor> {
    let bytes = driver_runtime_init_descriptor_bytes(descriptor)?;
    stage_driver_task_ring_frame(contract, bytes, 0)
}

/// Describe a pointer-free runtime initialization descriptor without copying.
#[cfg(feature = "kernel")]
pub fn describe_driver_runtime_init_descriptor(
    descriptor: &DriverRuntimeInitDescriptor,
) -> Option<DriverFrameDescriptor> {
    let bytes = driver_runtime_init_descriptor_bytes(descriptor)?;
    describe_driver_task_ring_frame(bytes, 0)
}

#[cfg(feature = "kernel")]
pub fn driver_runtime_init_descriptor_bytes(
    descriptor: &DriverRuntimeInitDescriptor,
) -> Option<&[u8]> {
    if !descriptor.valid() || !descriptor.sealed_identity_self_consistent() {
        return None;
    }
    // SAFETY: `DriverRuntimeInitDescriptor` is `repr(C)`, primitive-only, and
    // bounded by the shared ABI crate. The resulting byte view is used only for
    // immediate staged publication while `descriptor` is still borrowed.
    let bytes = unsafe {
        core::slice::from_raw_parts(
            core::ptr::from_ref(descriptor).cast::<u8>(),
            core::mem::size_of::<DriverRuntimeInitDescriptor>(),
        )
    };
    Some(bytes)
}

#[cfg(feature = "kernel")]
const BCM2711_SDIO_RUNTIME_IRQ: u32 = 158;
#[cfg(feature = "kernel")]
const BCM2711_SDIO_RUNTIME_IRQ_BADGE: u32 = BCM2711_SDIO_RUNTIME_IRQ + 1;

#[cfg(feature = "kernel")]
fn generated_cyw43_sdio_runtime_topology_sealed(
    hot_path: DriverTaskHotPath,
    task_key: u32,
    descriptor: &DriverRuntimeInitDescriptor,
) -> bool {
    let policy = crate::generated::driver_runtime_image_policy();
    if !policy.required
        || policy.irqs.len() != 1
        || policy.bus_links.len() != 1
        || descriptor.bus_link_count != 1
    {
        return false;
    }
    let generated_irq = policy.irqs[0];
    let generated_link = policy.bus_links[0];
    if generated_irq.hot_path != DriverTaskHotPath::SdioHost.as_str()
        || generated_irq.irq != BCM2711_SDIO_RUNTIME_IRQ
        || generated_irq.badge != BCM2711_SDIO_RUNTIME_IRQ_BADGE
        || u32::from(generated_irq.handler_slot) != DRIVER_TASK_CHILD_IRQ_HANDLER_BASE_SLOT
        || u32::from(generated_irq.notification_slot) != DRIVER_RUNTIME_LOCAL_NOTIFICATION_SLOT
        || generated_irq.trigger != crate::generated::DriverRuntimeIrqTrigger::Level
        || generated_link.channel != "cyw43-sdio"
        || generated_link.client_hot_path != DriverTaskHotPath::Cyw43Wifi.as_str()
        || generated_link.owner_hot_path != DriverTaskHotPath::SdioHost.as_str()
        || u32::from(generated_link.client_notification_slot)
            != DRIVER_RUNTIME_LOCAL_NOTIFICATION_SLOT
        || u32::from(generated_link.owner_notification_slot)
            != DRIVER_RUNTIME_LOCAL_NOTIFICATION_SLOT
        || u32::from(generated_link.client_to_owner_slot)
            != DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_SLOT
        || u32::from(generated_link.owner_to_client_slot)
            != DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_SLOT
        || generated_link.shared_offset != u32::from(DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE)
        || generated_link.shared_len != u32::from(DRIVER_RUNTIME_SDIO_SHARED_PAYLOAD_BYTES)
        || generated_link.link_epoch == 0
        || generated_link.event_offset != DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET
        || generated_link.event_len != DRIVER_RUNTIME_DPC_EVENT_RING_BYTES
        || usize::from(generated_link.event_depth) != DRIVER_RUNTIME_DPC_EVENT_RING_DEPTH
    {
        return false;
    }

    let link = descriptor.bus_links[0];
    let (role_flag, peer_hot_path, local_slot, peer_slot) = match hot_path {
        DriverTaskHotPath::Cyw43Wifi => (
            DRIVER_RUNTIME_BUS_LINK_FLAG_CLIENT,
            DriverTaskHotPath::SdioHost.as_u32(),
            u32::from(generated_link.client_notification_slot),
            u32::from(generated_link.client_to_owner_slot),
        ),
        DriverTaskHotPath::SdioHost => (
            DRIVER_RUNTIME_BUS_LINK_FLAG_OWNER,
            DriverTaskHotPath::Cyw43Wifi.as_u32(),
            u32::from(generated_link.owner_notification_slot),
            u32::from(generated_link.owner_to_client_slot),
        ),
        _ => return false,
    };
    let expected_flags = role_flag
        | DRIVER_RUNTIME_BUS_LINK_FLAG_POINTER_FREE
        | DRIVER_RUNTIME_BUS_LINK_FLAG_NOTIFICATIONS
        | DRIVER_RUNTIME_BUS_LINK_FLAG_DPC_EVENT_RING;
    let link_matches = link.owner_hot_path == DriverTaskHotPath::SdioHost.as_u32()
        && link.channel_id == DRIVER_RUNTIME_BUS_LINK_CHANNEL_CYW43_SDIO
        && link.shared_offset == generated_link.shared_offset
        && link.shared_len == generated_link.shared_len
        && link.flags == expected_flags
        && link.peer_hot_path == peer_hot_path
        && link.shared_epoch == generated_link.link_epoch
        && link.local_notification_slot == local_slot
        && link.peer_notification_slot == peer_slot
        && link.event_offset == generated_link.event_offset
        && link.event_len == generated_link.event_len
        && link.event_depth == generated_link.event_depth
        && link.notification_dpc_valid()
        && descriptor.has_sealed_pointer_free_bus_link(
            task_key,
            DriverTaskHotPath::SdioHost.as_u32(),
            DRIVER_RUNTIME_BUS_LINK_CHANNEL_CYW43_SDIO,
        );
    if !link_matches {
        return false;
    }

    match hot_path {
        DriverTaskHotPath::Cyw43Wifi => {
            descriptor.irq_count == 0
                && descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_POLL_ONLY != 0
                && descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_IRQS_BOUND == 0
        }
        DriverTaskHotPath::SdioHost => {
            let expected_trigger = match generated_irq.trigger {
                crate::generated::DriverRuntimeIrqTrigger::Level => {
                    DRIVER_RUNTIME_IRQ_TRIGGER_LEVEL
                }
                crate::generated::DriverRuntimeIrqTrigger::Edge => {
                    pi4_driver_abi::DRIVER_RUNTIME_IRQ_TRIGGER_EDGE
                }
            };
            let irq = descriptor.irqs[0];
            descriptor.irq_count == 1
                && descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_IRQS_BOUND != 0
                && descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_POLL_ONLY == 0
                && irq.irq == generated_irq.irq
                && irq.badge == generated_irq.badge
                && irq.handler_slot == u32::from(generated_irq.handler_slot)
                && irq.notification_slot == u32::from(generated_irq.notification_slot)
                && irq.trigger == expected_trigger
        }
        _ => false,
    }
}

#[cfg(feature = "kernel")]
fn driver_runtime_descriptor_expected_bus_link_sealed(
    hot_path: DriverTaskHotPath,
    task_key: u32,
    descriptor: &DriverRuntimeInitDescriptor,
) -> bool {
    match hot_path {
        DriverTaskHotPath::UsbKeyboard => descriptor.has_sealed_pointer_free_bus_link(
            task_key,
            DriverTaskHotPath::PcieRoot.as_u32(),
            DRIVER_RUNTIME_BUS_LINK_CHANNEL_USB_PCIE,
        ),
        DriverTaskHotPath::Cyw43Wifi | DriverTaskHotPath::SdioHost => {
            generated_cyw43_sdio_runtime_topology_sealed(hot_path, task_key, descriptor)
        }
        _ => descriptor.bus_link_count == 0,
    }
}

/// Record that one runtime init descriptor was sealed and accepted by a child.
#[cfg(feature = "kernel")]
pub fn record_driver_runtime_descriptor_seal(
    contract: DriverTaskContract,
    hot_path: DriverTaskHotPath,
    descriptor: &DriverRuntimeInitDescriptor,
) -> bool {
    let Some(task_key) = driver_task_contract_key(contract) else {
        return false;
    };
    if hot_path.contract() != contract
        || descriptor.hot_path != hot_path.as_u32()
        || descriptor.role_bit != hot_path.role_bit() as u32
        || !descriptor.sealed_identity_valid_for_task(task_key as u32)
        || !driver_runtime_descriptor_expected_bus_link_sealed(
            hot_path,
            task_key as u32,
            descriptor,
        )
    {
        return false;
    }
    DRIVER_TASK_RUNTIME_DESCRIPTOR_SEAL_HOT_PATH_MASK
        .fetch_or(hot_path.owner_state_bit(), Ordering::AcqRel);
    true
}

#[cfg(feature = "kernel")]
fn driver_runtime_descriptor_seal_registered(hot_path: DriverTaskHotPath) -> bool {
    DRIVER_TASK_RUNTIME_DESCRIPTOR_SEAL_HOT_PATH_MASK.load(Ordering::Acquire)
        & hot_path.owner_state_bit()
        != 0
}

#[cfg(feature = "kernel")]
fn driver_runtime_descriptor_bus_link_seal_label(
    hot_path: DriverTaskHotPath,
    descriptor_sealed: bool,
) -> &'static str {
    if !descriptor_sealed {
        return "missing";
    }
    match hot_path {
        DriverTaskHotPath::UsbKeyboard
        | DriverTaskHotPath::Cyw43Wifi
        | DriverTaskHotPath::SdioHost => "valid",
        _ => "none",
    }
}

/// Build a runtime init command for a Pi 4 hot path.
#[cfg(feature = "kernel")]
#[must_use]
pub const fn runtime_init_command(
    hot_path: DriverTaskHotPath,
    budget: DriverTaskBudgetGrant,
    frame: DriverFrameDescriptor,
) -> DriverTaskCommandRecord {
    DriverTaskCommandRecord {
        sequence: 0,
        opcode: DriverTaskOpcode::Service.as_u16(),
        flags: DRIVER_TASK_RING_FLAG_INIT_DESCRIPTOR_NON_ACCEPTANCE,
        arg0: hot_path.as_u32(),
        arg1: hot_path.role_bit() as u32,
        aux0: DRIVER_RUNTIME_INIT_AUX,
        aux1: 0,
        budget,
        frame,
    }
}

/// Build a runtime engine-init service command for a Pi 4 hot path.
#[cfg(feature = "kernel")]
#[must_use]
pub const fn runtime_engine_init_command(
    hot_path: DriverTaskHotPath,
    budget: DriverTaskBudgetGrant,
) -> DriverTaskCommandRecord {
    DriverTaskCommandRecord {
        sequence: 0,
        opcode: DriverTaskOpcode::Service.as_u16(),
        flags: 0,
        arg0: hot_path.as_u32(),
        arg1: hot_path.role_bit() as u32,
        aux0: DRIVER_RUNTIME_ENGINE_INIT_AUX,
        aux1: 0,
        budget,
        frame: DriverFrameDescriptor {
            offset: 0,
            len: 0,
            flags: 0,
        },
    }
}

/// Record a runtime-init descriptor that must be replayed after the shell.
#[cfg(feature = "kernel")]
pub fn record_deferred_runtime_init_descriptor(
    contract: DriverTaskContract,
    descriptor: DriverRuntimeInitDescriptor,
) -> bool {
    let Some(hot_path) = DriverTaskHotPath::from_u32(descriptor.hot_path) else {
        return false;
    };
    let Some(task_key) = driver_task_contract_key(contract) else {
        return false;
    };
    if hot_path.contract() != contract
        || descriptor.role_bit != hot_path.role_bit() as u32
        || !descriptor.valid()
        || !descriptor.sealed_identity_valid_for_task(task_key as u32)
    {
        emit_driver_task_resource_init_status(
            contract,
            hot_path,
            "runtime-descriptor-record",
            "invalid-descriptor",
            None,
        );
        return false;
    }
    deferred_runtime_init_slot(hot_path).store(descriptor);
    emit_driver_task_resource_init_status(
        contract,
        hot_path,
        "runtime-descriptor-record",
        "deferred",
        None,
    );
    true
}

/// Retain a sealed, manifest-derived descriptor for root-authoritative runtime recovery.
#[cfg(feature = "kernel")]
pub fn retain_driver_runtime_restart_descriptor(
    contract: DriverTaskContract,
    descriptor: DriverRuntimeInitDescriptor,
) -> bool {
    let Some(hot_path) = DriverTaskHotPath::from_u32(descriptor.hot_path) else {
        return false;
    };
    let Some(task_key) = driver_task_contract_key(contract) else {
        return false;
    };
    if hot_path.contract() != contract
        || descriptor.role_bit != hot_path.role_bit() as u32
        || !descriptor.valid()
        || !descriptor.sealed_identity_valid_for_task(task_key as u32)
    {
        return false;
    }
    deferred_runtime_init_slot(hot_path).retain(descriptor);
    true
}

#[cfg(feature = "kernel")]
fn retained_driver_runtime_restart_descriptor(
    hot_path: DriverTaskHotPath,
) -> Option<DriverRuntimeInitDescriptor> {
    let slot = deferred_runtime_init_slot(hot_path);
    if slot.retained.load(Ordering::Acquire) == 0 {
        return None;
    }
    Some(slot.load())
}

