/// Execute exactly one retained service-ring send or completion poll.
///
/// A missing completion keeps the exact request active. The caller must return
/// to the outer event pump before invoking this function again.
#[cfg(feature = "kernel")]
pub fn run_driver_task_ring_service_retained_turn(
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
) -> Option<DriverTaskCompletionRecord> {
    run_driver_task_ring_service_with_mode(
        contract,
        command,
        DriverTaskRingCommandMode::RetainedTurn,
    )
}

/// Typed result from one retained linked-runtime service turn.
///
/// `Pending` means the exact immutable command remains owned by the transport
/// across its prepare, scheduler, publication, notification, or completion-poll
/// phase. Callers must not reinterpret that normal multi-turn state as a missed
/// reply. `Failed` means no matching retained request survived the turn.
#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum DriverTaskRetainedServiceTurn {
    /// The exact command remains retained for a later outer event turn.
    Pending,
    /// The runtime published a terminal completion for the exact command.
    Complete(DriverTaskCompletionRecord),
    /// The transport could not retain or complete the exact command.
    Failed,
}

#[cfg(feature = "kernel")]
fn classify_driver_task_retained_service_turn(
    completion: Option<DriverTaskCompletionRecord>,
    active: Option<DriverTaskRetainedRequestSnapshot>,
    mut requested: DriverTaskCommandRecord,
    expected_command_fingerprint: u32,
) -> DriverTaskRetainedServiceTurn {
    let Some(active) = active else {
        return DriverTaskRetainedServiceTurn::Failed;
    };
    if expected_command_fingerprint == 0
        || active.command_fingerprint != expected_command_fingerprint
    {
        return DriverTaskRetainedServiceTurn::Failed;
    }
    let Some(mut retained) = active.state.command() else {
        return DriverTaskRetainedServiceTurn::Failed;
    };
    requested.sequence = active.state.request();
    requested.flags =
        driver_task_ring_flags_for_mode(DriverTaskRingCommandMode::RetainedTurn, requested.flags);
    retained.sequence = active.state.request();
    let identity_matches = retained == requested;
    if let Some(completion) = completion {
        if active.state.issued()
            && identity_matches
            && completion.sequence == active.state.request()
        {
            DriverTaskRetainedServiceTurn::Complete(completion)
        } else {
            DriverTaskRetainedServiceTurn::Failed
        }
    } else if identity_matches {
        DriverTaskRetainedServiceTurn::Pending
    } else {
        DriverTaskRetainedServiceTurn::Failed
    }
}

/// Execute one retained service-ring turn and preserve Pending as a first-class
/// outcome rather than overloading `None` as both progress and failure.
#[cfg(feature = "kernel")]
pub fn run_driver_task_ring_service_retained_service_turn(
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
) -> DriverTaskRetainedServiceTurn {
    // Successful completion clears the production slot, so retain the exact
    // pre-turn identity independently for terminal validation. Pending instead
    // validates the post-turn state created or advanced by this outer turn.
    let mut fingerprint_command = command;
    fingerprint_command.flags = driver_task_ring_flags_for_mode(
        DriverTaskRingCommandMode::RetainedTurn,
        fingerprint_command.flags,
    );
    let expected_command_fingerprint = driver_task_ring_command_fingerprint(fingerprint_command, 0);
    let active_before = active_driver_task_retained_request_snapshot(contract);
    let completion = run_driver_task_ring_service_retained_turn(contract, command);
    let active = if completion.is_some() {
        active_before
    } else {
        active_driver_task_retained_request_snapshot(contract)
    };
    classify_driver_task_retained_service_turn(
        completion,
        active,
        command,
        expected_command_fingerprint,
    )
}

/// Execute one retained service turn with atomic staged-byte publication.
#[cfg(feature = "kernel")]
pub fn run_driver_task_ring_service_retained_turn_staged(
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
    staging_segments: &[DriverTaskStagingSegment<'_>],
) -> Option<DriverTaskCompletionRecord> {
    run_driver_task_ring_service_with_mode_and_staging(
        contract,
        command,
        DriverTaskRingCommandMode::RetainedTurn,
        staging_segments,
    )
}

/// Execute one staged retained turn with a typed terminal transport outcome.
///
/// As with the non-staged sibling, a successful completion clears the live
/// slot, so classification uses the pre-turn immutable identity. A pending
/// turn instead validates the post-turn identity and staged command retained by
/// the HAL. This keeps serial TX failure distinct from ordinary backpressure.
#[cfg(feature = "kernel")]
pub fn run_driver_task_ring_service_retained_service_turn_staged(
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
    staging_segments: &[DriverTaskStagingSegment<'_>],
) -> DriverTaskRetainedServiceTurn {
    let mut fingerprint_command = command;
    fingerprint_command.flags = driver_task_ring_flags_for_mode(
        DriverTaskRingCommandMode::RetainedTurn,
        fingerprint_command.flags,
    );
    let expected_command_fingerprint = driver_task_ring_command_fingerprint(
        fingerprint_command,
        driver_task_staging_segments_fingerprint(staging_segments),
    );
    let active_before = active_driver_task_retained_request_snapshot(contract);
    let completion =
        run_driver_task_ring_service_retained_turn_staged(contract, command, staging_segments);
    let active = if completion.is_some() {
        active_before
    } else {
        active_driver_task_retained_request_snapshot(contract)
    };
    classify_driver_task_retained_service_turn(
        completion,
        active,
        command,
        expected_command_fingerprint,
    )
}

/// Emit a non-acceptance resource-initialization breadcrumb for one hot path.
#[cfg(feature = "kernel")]
pub fn emit_driver_task_resource_init_status(
    contract: DriverTaskContract,
    hot_path: DriverTaskHotPath,
    stage: &'static str,
    status: &'static str,
    completion: Option<DriverTaskCompletionRecord>,
) {
    emit_driver_task_resource_init_status_with_context(
        contract, hot_path, stage, status, completion, None, None,
    );
}

#[cfg(feature = "kernel")]
fn emit_driver_task_resource_init_status_with_context(
    contract: DriverTaskContract,
    hot_path: DriverTaskHotPath,
    stage: &'static str,
    status: &'static str,
    completion: Option<DriverTaskCompletionRecord>,
    expected_aux0: Option<u32>,
    expected_request: Option<u32>,
) {
    use core::fmt::Write;
    use heapless::String;

    let active_request = active_driver_task_ring_request(contract);
    let progress = latest_driver_task_ring_progress(contract);
    let progress_request_match = match (active_request, progress) {
        (Some(request), Some(progress))
            if progress.marker_valid && progress.sequence == request as u32 =>
        {
            "yes"
        }
        (Some(_), Some(_)) => "no",
        (Some(_), None) => "no-progress",
        (None, Some(_)) => "no-active-request",
        (None, None) => "none",
    };
    let expected_request = expected_request.filter(|request| *request != 0);
    let expected_aux0_valid = expected_aux0.is_some();
    let expected_request_valid = expected_request.is_some();
    let expected_aux0_value = expected_aux0.unwrap_or(0);
    let expected_request_value = expected_request.unwrap_or(0);
    let same_request_resume = match (expected_request, active_request) {
        (Some(expected), Some(active)) if expected == active as u32 => "yes",
        (Some(_), Some(_)) => "no",
        (Some(_), None) => "no-active-request",
        (None, Some(_)) => "unknown",
        (None, None) => "none",
    };
    let Some(repeat_count) = driver_task_resource_log_repeat_count(
        contract,
        hot_path,
        stage,
        status,
        completion,
        expected_aux0_value,
        expected_request_value,
        active_request,
        progress,
    ) else {
        return;
    };
    let mut line = String::<1024>::new();
    if let Some(completion) = completion {
        let _ = write!(
            line,
            "DRIVER_TASK_RESOURCE_INIT contract={} hot_path={} stage={} status={} acceptance=no code={} detail={} result={} frame_len={} owner=linked-runtime root_action={} blocker={}-{} next_action={} active_request_valid={} active_request={} expected_request_valid={} expected_request={} expected_aux0_valid={} expected_aux0=0x{:08x} same_request_resume={} progress_marker_valid={} progress_sequence={} progress_phase={} progress_phase_name={} progress_aux0=0x{:08x} progress_request_match={}",
            contract.name,
            hot_path.as_str(),
            stage,
            status,
            completion.code,
            completion.detail,
            completion.result,
            completion.frame.len,
            driver_task_resource_root_action(stage, status),
            stage,
            status,
            driver_task_resource_next_action(stage, status),
            active_request.map_or("no", |_| "yes"),
            active_request.unwrap_or(0),
            if expected_request_valid { "yes" } else { "no" },
            expected_request_value,
            if expected_aux0_valid { "yes" } else { "no" },
            expected_aux0_value,
            same_request_resume,
            progress.map_or("no", |progress| {
                if progress.marker_valid { "yes" } else { "no" }
            }),
            progress.map_or(0, |progress| progress.sequence),
            progress.map_or(0, |progress| progress.phase),
            progress.map_or("none", |progress| progress.phase_name),
            progress.map_or(0, |progress| progress.aux0),
            progress_request_match,
        );
    } else {
        let _ = write!(
            line,
            "DRIVER_TASK_RESOURCE_INIT contract={} hot_path={} stage={} status={} acceptance=no code=none detail=none result=none frame_len=0 owner=linked-runtime root_action={} blocker={}-{} next_action={} active_request_valid={} active_request={} expected_request_valid={} expected_request={} expected_aux0_valid={} expected_aux0=0x{:08x} same_request_resume={} progress_marker_valid={} progress_sequence={} progress_phase={} progress_phase_name={} progress_aux0=0x{:08x} progress_request_match={}",
            contract.name,
            hot_path.as_str(),
            stage,
            status,
            driver_task_resource_root_action(stage, status),
            stage,
            status,
            driver_task_resource_next_action(stage, status),
            active_request.map_or("no", |_| "yes"),
            active_request.unwrap_or(0),
            if expected_request_valid { "yes" } else { "no" },
            expected_request_value,
            if expected_aux0_valid { "yes" } else { "no" },
            expected_aux0_value,
            same_request_resume,
            progress.map_or("no", |progress| {
                if progress.marker_valid { "yes" } else { "no" }
            }),
            progress.map_or(0, |progress| progress.sequence),
            progress.map_or(0, |progress| progress.phase),
            progress.map_or("none", |progress| progress.phase_name),
            progress.map_or(0, |progress| progress.aux0),
            progress_request_match,
        );
    }
    if repeat_count > 1 {
        let _ = write!(line, " repeat_count={}", repeat_count);
    }
    if driver_task_resource_status_requires_uart(contract, hot_path, stage, status) {
        crate::bootstrap::log::force_uart_line_raw(line.as_str());
    } else if driver_task_resource_status_logs_to_buffer(contract, hot_path, stage, status) {
        crate::bootstrap::log::force_log_buffer_line_or_uart_without_prompt_refresh(line.as_str());
    } else {
        crate::bootstrap::log::force_uart_line(line.as_str());
    }
    emit_driver_task_resource_init_hdmi_progress(contract, hot_path, stage, status, completion);
}

#[cfg(feature = "kernel")]
fn driver_task_resource_root_action(stage: &str, status: &str) -> &'static str {
    if stage == "runtime-ring-submit" {
        "submit-turn"
    } else if stage.contains("descriptor") || status == "descriptor-rejected" {
        "publish-descriptor"
    } else if stage.contains("owner-state") {
        "register-owner-state"
    } else if status == "begin" || status == "retry" {
        "submit-turn"
    } else {
        "observe-evidence"
    }
}

#[cfg(feature = "kernel")]
fn driver_task_resource_next_action(stage: &str, status: &str) -> &'static str {
    match status {
        "no-endpoint" | "ring-missing" | "slot-missing" => "replay-runtime-bootstrap",
        "stage-invalid" | "stage-failed" | "invalid-contract" | "descriptor-rejected" => {
            "fix-driver-task-descriptor"
        }
        "busy" => "poll-active-request",
        "no-reply" => "inspect-linked-runtime-progress",
        "tx-no-reply" => "inspect-control-tx-progress",
        "tx-submit-fail" => "inspect-runtime-completion",
        "begin" | "retry" => "wait-for-linked-runtime-reply",
        "ready" => "continue-next-driver-gate",
        "failed" | "fault" | "poll-fault" | "poll-unexpected" => "inspect-runtime-completion",
        "poll-timeout" => "inspect-control-rx-progress",
        _ if stage == "runtime-ring-submit" => "inspect-runtime-admission",
        _ if status.starts_with("blocked") => "satisfy-linked-runtime-prerequisite",
        _ => "continue-driver-debug",
    }
}

