    #[cfg(feature = "kernel")]
    #[test]
    fn retained_one_way_turn_keeps_a_demoted_pi_runtime_schedulable() {
        assert!(retained_priority_boost_required(true, true, 160));
        assert!(retained_priority_boost_required(true, true, 200));
        assert!(!retained_priority_boost_required(false, true, 160));
        assert!(!retained_priority_boost_required(true, false, 160));
        assert!(!retained_priority_boost_required(true, true, 0));
        assert!(!retained_priority_boost_required(true, true, 255));

        let mask = DRIVER_TASK_RETAINED_LEASE_BUS | DRIVER_TASK_RETAINED_LEASE_PRIMARY;
        let mut phase = DriverTaskRetainedLeasePhase::BoostBus;
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::BoostBus
        );
        phase = phase.after_success(mask);
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::BoostPrimary
        );
        phase = phase.after_success(mask);
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::CommitRing
        );
        phase = DriverTaskRetainedLeasePhase::Committed;
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::NotifyRing
        );
        phase = DriverTaskRetainedLeasePhase::Issued;
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::PollRing
        );

        phase = DriverTaskRetainedLeasePhase::RestorePrimary;
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::RestorePrimary
        );
        phase = phase.after_success(mask);
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::RestoreBus
        );
        phase = phase.after_success(mask);
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::Complete
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn deferred_steady_priority_cutover_is_claimed_exactly_once() {
        let slot = DriverTaskCommandSlot::new();
        assert_eq!(
            DriverTaskSteadyPriorityState::from_usize(
                slot.steady_priority_state.load(Ordering::Acquire),
            ),
            Some(DriverTaskSteadyPriorityState::Bootstrap),
        );
        assert!(claim_driver_task_steady_priority_cutover(&slot));
        assert!(!claim_driver_task_steady_priority_cutover(&slot));
        assert!(resolve_driver_task_steady_priority_cutover(&slot, true));
        assert!(driver_task_steady_priority_is_active(&slot));
        assert!(!claim_driver_task_steady_priority_cutover(&slot));
        assert!(!resolve_driver_task_steady_priority_cutover(&slot, true));
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn failed_steady_priority_cutover_stays_failed_until_explicit_restart_reset() {
        let slot = DriverTaskCommandSlot::new();
        assert!(claim_driver_task_steady_priority_cutover(&slot));
        assert!(resolve_driver_task_steady_priority_cutover(&slot, false));
        assert_eq!(
            DriverTaskSteadyPriorityState::from_usize(
                slot.steady_priority_state.load(Ordering::Acquire),
            ),
            Some(DriverTaskSteadyPriorityState::CutoverFailed),
        );
        assert!(!claim_driver_task_steady_priority_cutover(&slot));
        assert!(!resolve_driver_task_steady_priority_cutover(&slot, false));

        reset_driver_task_steady_priority_for_bootstrap(&slot);
        assert!(claim_driver_task_steady_priority_cutover(&slot));
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn retained_poll_miss_arms_one_endpoint_rendezvous_or_quarantines_the_request() {
        let slot = DriverTaskCommandSlot::new();
        let command = DriverTaskCommandRecord::service(
            0,
            DriverTaskBudgetGrant::from_contract(SDIO_HOST_DRIVER_TASK_CONTRACT),
        );
        let generation = CYW43_SDIO_PAIR_RESTART_EPOCH.load(Ordering::Acquire);
        slot.retained_priority_lease_request
            .store(77, Ordering::Release);
        slot.retained_priority_lease_fingerprint
            .store(0x1234_5679, Ordering::Release);
        slot.retained_priority_lease_generation
            .store(generation, Ordering::Release);
        slot.retained_priority_lease_phase.store(
            DriverTaskRetainedLeasePhase::Issued.as_usize(),
            Ordering::Release,
        );
        slot.retained_doorbell_issued.store(1, Ordering::Release);

        assert!(!arm_driver_task_retained_priority_lease_wake_retry(
            &slot,
            SDIO_HOST_DRIVER_TASK_CONTRACT,
            command,
            0,
            78,
            0x1234_5679,
        ));
        assert!(!arm_driver_task_retained_priority_lease_wake_retry(
            &slot,
            SDIO_HOST_DRIVER_TASK_CONTRACT,
            command,
            0,
            77,
            0xfeed_beef,
        ));
        assert!(arm_driver_task_retained_priority_lease_wake_retry(
            &slot,
            SDIO_HOST_DRIVER_TASK_CONTRACT,
            command,
            0,
            77,
            0x1234_5679,
        ));
        assert_eq!(
            DriverTaskRetainedLeasePhase::from_usize(
                slot.retained_priority_lease_phase.load(Ordering::Acquire),
            )
            .map(DriverTaskRetainedLeasePhase::operation),
            Some(DriverTaskRetainedLeaseOperation::NotifyRing),
        );
        assert!(!arm_driver_task_retained_priority_lease_wake_retry(
            &slot,
            SDIO_HOST_DRIVER_TASK_CONTRACT,
            command,
            0,
            77,
            0x1234_5679,
        ));

        let usb_slot = DriverTaskCommandSlot::new();
        usb_slot.active.store(1, Ordering::Release);
        usb_slot.request_seq.store(81, Ordering::Release);
        usb_slot
            .active_command_fingerprint
            .store(0x7654_3211, Ordering::Release);
        usb_slot
            .retained_priority_lease_request
            .store(81, Ordering::Release);
        usb_slot
            .retained_priority_lease_fingerprint
            .store(0x7654_3211, Ordering::Release);
        usb_slot
            .retained_priority_lease_generation
            .store(0, Ordering::Release);
        usb_slot.retained_priority_lease_phase.store(
            DriverTaskRetainedLeasePhase::Issued.as_usize(),
            Ordering::Release,
        );
        usb_slot
            .retained_doorbell_issued
            .store(1, Ordering::Release);
        assert!(arm_driver_task_retained_priority_lease_wake_retry(
            &usb_slot,
            USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
            command,
            0,
            81,
            0x7654_3211,
        ));
        assert_eq!(
            DriverTaskRetainedLeasePhase::from_usize(
                usb_slot
                    .retained_priority_lease_phase
                    .load(Ordering::Acquire),
            )
            .map(DriverTaskRetainedLeasePhase::operation),
            Some(DriverTaskRetainedLeaseOperation::NotifyRing),
        );
        assert!(!arm_driver_task_retained_priority_lease_wake_retry(
            &usb_slot,
            USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
            command,
            0,
            81,
            0x7654_3211,
        ));
        poison_driver_task_retained_request(&usb_slot);
        assert_eq!(
            DriverTaskRetainedLeasePhase::from_usize(
                usb_slot
                    .retained_priority_lease_phase
                    .load(Ordering::Acquire),
            ),
            Some(DriverTaskRetainedLeasePhase::Poisoned),
        );
        assert_eq!(usb_slot.active.load(Ordering::Acquire), 1);
        assert_eq!(usb_slot.request_seq.load(Ordering::Acquire), 81);
        assert_eq!(
            usb_slot.active_command_fingerprint.load(Ordering::Acquire),
            0x7654_3211,
        );
        assert_eq!(usb_slot.retained_doorbell_issued.load(Ordering::Acquire), 1);
        assert!(!arm_driver_task_retained_priority_lease_wake_retry(
            &usb_slot,
            USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
            command,
            0,
            81,
            0x7654_3211,
        ));
        assert!(matches!(
            active_driver_task_retained_request_for_slot(&usb_slot),
            Some(DriverTaskRetainedRequestState::Invalid { request: 81 })
        ));
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn non_pair_retained_faults_never_request_cyw43_sdio_recovery() {
        fn seed_retained_slot(slot: &DriverTaskCommandSlot, issued: bool) {
            slot.active.store(1, Ordering::Release);
            slot.request_seq.store(91, Ordering::Release);
            slot.active_command_fingerprint
                .store(0x1020_3041, Ordering::Release);
            slot.retained_priority_lease_request
                .store(91, Ordering::Release);
            slot.retained_priority_lease_fingerprint
                .store(0x1020_3041, Ordering::Release);
            slot.retained_priority_lease_generation.store(
                CYW43_SDIO_PAIR_RESTART_EPOCH.load(Ordering::Acquire),
                Ordering::Release,
            );
            slot.retained_priority_lease_phase.store(
                if issued {
                    DriverTaskRetainedLeasePhase::Issued
                } else {
                    DriverTaskRetainedLeasePhase::ReadyToIssue
                }
                .as_usize(),
                Ordering::Release,
            );
            slot.retained_doorbell_issued
                .store(usize::from(issued), Ordering::Release);
        }

        for contract in [
            USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
            SERIAL_DRIVER_TASK_CONTRACT,
            HDMI_TEXT_DRIVER_TASK_CONTRACT,
        ] {
            reset_cyw43_sdio_pair_recovery_for_test();
            let pre_issue = DriverTaskCommandSlot::new();
            seed_retained_slot(&pre_issue, false);
            fail_driver_task_retained_priority_lease(&pre_issue, contract);
            assert!(
                !cyw43_sdio_pair_restart_required(),
                "pre-issue {} fault must not restart Wi-Fi",
                contract.name,
            );
            assert_eq!(pre_issue.active.load(Ordering::Acquire), 0);
            assert_eq!(
                DriverTaskRetainedLeasePhase::from_usize(
                    pre_issue
                        .retained_priority_lease_phase
                        .load(Ordering::Acquire),
                ),
                Some(DriverTaskRetainedLeasePhase::Inactive),
            );

            let issued = DriverTaskCommandSlot::new();
            seed_retained_slot(&issued, true);
            fail_driver_task_retained_priority_lease(&issued, contract);
            assert!(
                !cyw43_sdio_pair_restart_required(),
                "issued-unknown {} fault must remain device-local",
                contract.name,
            );
            assert_eq!(issued.active.load(Ordering::Acquire), 1);
            assert_eq!(issued.request_seq.load(Ordering::Acquire), 91);
            assert_eq!(
                issued.active_command_fingerprint.load(Ordering::Acquire),
                0x1020_3041,
            );
            assert_eq!(
                DriverTaskRetainedLeasePhase::from_usize(
                    issued.retained_priority_lease_phase.load(Ordering::Acquire),
                ),
                Some(DriverTaskRetainedLeasePhase::Poisoned),
            );
        }

        for contract in [
            SDIO_HOST_DRIVER_TASK_CONTRACT,
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
        ] {
            reset_cyw43_sdio_pair_recovery_for_test();
            let pre_issue = DriverTaskCommandSlot::new();
            seed_retained_slot(&pre_issue, false);
            fail_driver_task_retained_priority_lease(&pre_issue, contract);
            assert!(
                !cyw43_sdio_pair_restart_required(),
                "pre-issue {} contention must clear without pair recovery",
                contract.name,
            );
            assert_eq!(pre_issue.active.load(Ordering::Acquire), 0);

            let issued = DriverTaskCommandSlot::new();
            seed_retained_slot(&issued, true);
            fail_driver_task_retained_priority_lease(&issued, contract);
            assert!(
                cyw43_sdio_pair_restart_required(),
                "issued-unknown {} fault must request pair recovery",
                contract.name,
            );
            assert_eq!(issued.active.load(Ordering::Acquire), 1);
        }
        reset_cyw43_sdio_pair_recovery_for_test();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn retained_service_turn_preserves_pending_and_rejects_aliases() {
        let mut requested = DriverTaskCommandRecord::pi4_hot_path(
            0,
            DriverTaskHotPath::UsbKeyboard,
            DriverTaskBudgetGrant::from_contract(USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT),
            DriverFrameDescriptor {
                offset: 0,
                len: 0,
                flags: 0,
            },
        );
        requested.aux0 = 0x5542_0001;
        let mut retained = requested;
        retained.sequence = 19;
        retained.flags = driver_task_ring_flags_for_mode(
            DriverTaskRingCommandMode::RetainedTurn,
            retained.flags,
        );
        let command_fingerprint = driver_task_ring_command_fingerprint(retained, 0);
        let snapshot = |state| {
            Some(DriverTaskRetainedRequestSnapshot {
                state,
                command_fingerprint,
            })
        };
        assert_eq!(
            classify_driver_task_retained_service_turn(
                None,
                snapshot(DriverTaskRetainedRequestState::Prepared {
                    request: 19,
                    command: retained,
                }),
                requested,
                command_fingerprint,
            ),
            DriverTaskRetainedServiceTurn::Pending,
        );
        assert_eq!(
            classify_driver_task_retained_service_turn(
                None,
                snapshot(DriverTaskRetainedRequestState::Issued {
                    request: 19,
                    command: retained,
                }),
                requested,
                command_fingerprint,
            ),
            DriverTaskRetainedServiceTurn::Pending,
        );

        let exact_completion = DriverTaskCompletionRecord::progress(19, 1);
        assert_eq!(
            classify_driver_task_retained_service_turn(
                Some(exact_completion),
                snapshot(DriverTaskRetainedRequestState::Issued {
                    request: 19,
                    command: retained,
                }),
                requested,
                command_fingerprint,
            ),
            DriverTaskRetainedServiceTurn::Complete(exact_completion),
        );
        let stale_completion = DriverTaskCompletionRecord::progress(18, 1);
        assert_eq!(
            classify_driver_task_retained_service_turn(
                Some(stale_completion),
                snapshot(DriverTaskRetainedRequestState::Issued {
                    request: 19,
                    command: retained,
                }),
                requested,
                command_fingerprint,
            ),
            DriverTaskRetainedServiceTurn::Failed,
        );
        assert_eq!(
            classify_driver_task_retained_service_turn(
                Some(exact_completion),
                snapshot(DriverTaskRetainedRequestState::Prepared {
                    request: 19,
                    command: retained,
                }),
                requested,
                command_fingerprint,
            ),
            DriverTaskRetainedServiceTurn::Failed,
        );

        let mut aliased = retained;
        aliased.aux0 ^= 1;
        assert_eq!(
            classify_driver_task_retained_service_turn(
                None,
                snapshot(DriverTaskRetainedRequestState::Issued {
                    request: 19,
                    command: aliased,
                }),
                requested,
                command_fingerprint,
            ),
            DriverTaskRetainedServiceTurn::Failed,
        );
        assert_eq!(
            classify_driver_task_retained_service_turn(
                Some(exact_completion),
                snapshot(DriverTaskRetainedRequestState::Issued {
                    request: 19,
                    command: aliased,
                }),
                requested,
                command_fingerprint,
            ),
            DriverTaskRetainedServiceTurn::Failed,
        );
        assert_eq!(
            classify_driver_task_retained_service_turn(
                None,
                snapshot(DriverTaskRetainedRequestState::Invalid { request: 19 }),
                requested,
                command_fingerprint,
            ),
            DriverTaskRetainedServiceTurn::Failed,
        );
        assert_eq!(
            classify_driver_task_retained_service_turn(
                None,
                Some(DriverTaskRetainedRequestSnapshot {
                    state: DriverTaskRetainedRequestState::Issued {
                        request: 19,
                        command: retained,
                    },
                    command_fingerprint: command_fingerprint ^ 1,
                }),
                requested,
                command_fingerprint,
            ),
            DriverTaskRetainedServiceTurn::Failed,
        );
        assert_eq!(
            classify_driver_task_retained_service_turn(None, None, requested, command_fingerprint,),
            DriverTaskRetainedServiceTurn::Failed,
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn retained_ring_sequence_is_invisible_until_the_dedicated_issue_turn() {
        let slot = DriverTaskCommandSlot::new();
        let mut ring_page = Box::new(AlignedDriverTaskRing(
            [0u32; DRIVER_TASK_RING_PAGE_BYTES / core::mem::size_of::<u32>()],
        ));
        let ring_root_ptr = ring_page.0.as_mut_ptr() as usize;
        let command_ptr = ring_root_ptr as *mut DriverTaskCommandRecord;
        let completion_ptr =
            (ring_root_ptr + DRIVER_TASK_RING_COMPLETION_OFFSET) as *mut DriverTaskCompletionRecord;
        let mut command = runtime_engine_init_command(
            DriverTaskHotPath::Cyw43Wifi,
            DriverTaskBudgetGrant::from_contract(CYW43_WIFI_DRIVER_TASK_CONTRACT),
        );
        command.sequence = 73;
        command.flags = DRIVER_TASK_RING_FLAG_ONE_WAY;

        driver_task_ring_stage_command_record(
            &slot,
            ring_root_ptr,
            command_ptr,
            completion_ptr,
            command,
            DriverTaskCompletionRecord::fault(0, DriverTaskFaultCode::RejectedCommand),
        );

        let runtime_poll = || {
            // SAFETY: The aligned test-owned page carries the production ABI
            // command record. This is the same sequence-first intake boundary
            // used by the autonomously polling linked runtime.
            let candidate = unsafe { core::ptr::read_volatile(command_ptr) };
            (candidate.sequence != 0).then_some(candidate)
        };
        assert_eq!(runtime_poll(), None, "prepare turn stays ABI-invisible");

        let mask = DRIVER_TASK_RETAINED_LEASE_BUS | DRIVER_TASK_RETAINED_LEASE_PRIMARY;
        let mut phase = DriverTaskRetainedLeasePhase::BoostBus;
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::BoostBus
        );
        assert_eq!(runtime_poll(), None, "bus-boost turn cannot issue work");
        phase = phase.after_success(mask);
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::BoostPrimary
        );
        assert_eq!(runtime_poll(), None, "primary-boost turn cannot issue work");
        phase = phase.after_success(mask);
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::CommitRing
        );
        assert_eq!(
            runtime_poll(),
            None,
            "ready-to-issue is not itself an issue boundary"
        );

        slot.active.store(1, Ordering::Release);
        slot.ring_root_ptr.store(ring_root_ptr, Ordering::Release);
        slot.request_seq
            .store(command.sequence as usize, Ordering::Release);
        slot.retained_priority_lease_phase.store(
            DriverTaskRetainedLeasePhase::ReadyToIssue.as_usize(),
            Ordering::Release,
        );
        assert_eq!(runtime_poll(), None);
        assert!(matches!(
            active_driver_task_retained_request_for_slot(&slot),
            Some(DriverTaskRetainedRequestState::Prepared { request: 73, .. })
        ));

        // Production conservatively poisons replay before making the sequence
        // child-visible. The transient pre-publication state is invalid, then
        // the sequence-last commit becomes unambiguously issued.
        slot.retained_doorbell_issued.store(1, Ordering::Release);
        assert!(matches!(
            active_driver_task_retained_request_for_slot(&slot),
            Some(DriverTaskRetainedRequestState::Invalid { request: 73 })
        ));
        driver_task_ring_commit_command_sequence(
            &slot,
            ring_root_ptr,
            command_ptr,
            command.sequence,
        );
        assert_eq!(runtime_poll(), Some(command));
        assert!(matches!(
            active_driver_task_retained_request_for_slot(&slot),
            Some(DriverTaskRetainedRequestState::Invalid { request: 73 })
        ));
        assert!(mark_driver_task_retained_priority_lease_committed(
            &slot, false
        ));
        assert!(matches!(
            active_driver_task_retained_request_for_slot(&slot),
            Some(DriverTaskRetainedRequestState::Issued { request: 73, .. })
        ));
        phase = DriverTaskRetainedLeasePhase::Committed;
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::NotifyRing
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn root_retained_grant_is_exact_monotonic_and_rearmed_from_consumed_truth() {
        let slot = DriverTaskCommandSlot::new();
        let mut ring_page = Box::new(AlignedDriverTaskRing(
            [0u32; DRIVER_TASK_RING_PAGE_BYTES / core::mem::size_of::<u32>()],
        ));
        let ring_root_ptr = ring_page.0.as_mut_ptr() as usize;
        let mut command = DriverTaskCommandRecord::pi4_hot_path(
            73,
            DriverTaskHotPath::Cyw43Wifi,
            DriverTaskBudgetGrant::from_contract(CYW43_WIFI_DRIVER_TASK_CONTRACT),
            DriverFrameDescriptor {
                offset: 0,
                len: 0,
                flags: 0,
            },
        );
        command.flags |= DRIVER_TASK_RING_FLAG_ONE_WAY;
        command.aux0 = DRIVER_RUNTIME_CYW43_COMMAND_AUX;
        command.aux1 = 7;

        assert_eq!(next_driver_task_retained_grant_id(0), Some(1));
        assert_eq!(next_driver_task_retained_grant_id(1), Some(2));
        assert_eq!(next_driver_task_retained_grant_id(u32::MAX), None);
        assert!(driver_task_ring_publish_continuation_grant(
            &slot,
            ring_root_ptr,
            command,
            1,
        ));
        let grant = driver_task_ring_read_continuation_grant(ring_root_ptr)
            .expect("sequence-last root grant must be readable");
        assert!(driver_task_continuation_grant_matches(grant, command, 1));

        let lease_fingerprint = 0x1234_5679;
        slot.retained_priority_lease_request
            .store(command.sequence as usize, Ordering::Release);
        slot.retained_priority_lease_fingerprint
            .store(lease_fingerprint, Ordering::Release);
        slot.retained_priority_lease_generation.store(
            driver_task_retained_lease_generation(CYW43_WIFI_DRIVER_TASK_CONTRACT),
            Ordering::Release,
        );
        slot.retained_priority_lease_phase.store(
            DriverTaskRetainedLeasePhase::Issued.as_usize(),
            Ordering::Release,
        );
        slot.retained_doorbell_issued.store(1, Ordering::Release);
        slot.retained_grant_id.store(1, Ordering::Release);
        assert!(arm_driver_task_retained_priority_lease_wake_retry(
            &slot,
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
            command,
            ring_root_ptr,
            command.sequence as usize,
            lease_fingerprint,
        ));
        assert_eq!(
            DriverTaskRetainedLeasePhase::from_usize(
                slot.retained_priority_lease_phase.load(Ordering::Acquire),
            ),
            Some(DriverTaskRetainedLeasePhase::Granted),
            "an unconsumed exact grant is re-signalled without republishing authority",
        );

        slot.retained_priority_lease_phase.store(
            DriverTaskRetainedLeasePhase::Issued.as_usize(),
            Ordering::Release,
        );
        let consumed_ptr = (ring_root_ptr
            + usize::from(DRIVER_RUNTIME_CONTINUATION_GRANT_OFFSET)
            + core::mem::offset_of!(DriverRuntimeContinuationGrant, consumed_grant_id))
            as *mut u32;
        // SAFETY: `consumed_ptr` addresses the fixed consumed-id field in this
        // test-owned aligned ring page.
        unsafe {
            core::ptr::write_volatile(consumed_ptr, 1);
        }
        assert!(arm_driver_task_retained_priority_lease_wake_retry(
            &slot,
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
            command,
            ring_root_ptr,
            command.sequence as usize,
            lease_fingerprint,
        ));
        assert_eq!(
            DriverTaskRetainedLeasePhase::from_usize(
                slot.retained_priority_lease_phase.load(Ordering::Acquire),
            ),
            Some(DriverTaskRetainedLeasePhase::GrantRequired),
            "a consumed grant requires a fresh monotonic ticket on a later outer turn",
        );

        let mut stale_generation = command;
        stale_generation.aux1 = command.aux1.wrapping_add(1);
        assert!(!driver_task_continuation_grant_matches(
            grant,
            stale_generation,
            1,
        ));
        let mut mutated_action = command;
        mutated_action.arg0 ^= 1;
        assert!(!driver_task_continuation_grant_matches(
            grant,
            mutated_action,
            1,
        ));
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn retained_priority_lease_identity_rejects_request_fingerprint_and_generation_aliases() {
        let slot = DriverTaskCommandSlot::new();
        let generation = CYW43_SDIO_PAIR_RESTART_EPOCH.load(Ordering::Acquire);
        slot.retained_priority_lease_request
            .store(41, Ordering::Release);
        slot.retained_priority_lease_fingerprint
            .store(0x1234_5679, Ordering::Release);
        slot.retained_priority_lease_generation
            .store(generation, Ordering::Release);

        assert!(driver_task_retained_lease_identity_matches(
            &slot,
            SDIO_HOST_DRIVER_TASK_CONTRACT,
            41,
            0x1234_5679,
        ));
        assert!(!driver_task_retained_lease_identity_matches(
            &slot,
            SDIO_HOST_DRIVER_TASK_CONTRACT,
            42,
            0x1234_5679,
        ));
        assert!(!driver_task_retained_lease_identity_matches(
            &slot,
            SDIO_HOST_DRIVER_TASK_CONTRACT,
            41,
            0x1234_567b,
        ));
        slot.retained_priority_lease_generation
            .store(generation.wrapping_add(1), Ordering::Release);
        assert!(!driver_task_retained_lease_identity_matches(
            &slot,
            SDIO_HOST_DRIVER_TASK_CONTRACT,
            41,
            0x1234_5679,
        ));

        let serial_slot = DriverTaskCommandSlot::new();
        serial_slot
            .retained_priority_lease_request
            .store(41, Ordering::Release);
        serial_slot
            .retained_priority_lease_fingerprint
            .store(0x1234_5679, Ordering::Release);
        serial_slot
            .retained_priority_lease_generation
            .store(0, Ordering::Release);
        assert_eq!(
            driver_task_retained_lease_generation(SERIAL_DRIVER_TASK_CONTRACT),
            0,
        );
        assert!(driver_task_retained_lease_identity_matches(
            &serial_slot,
            SERIAL_DRIVER_TASK_CONTRACT,
            41,
            0x1234_5679,
        ));
    }

    #[test]
    fn pi4_pre_root_runtime_init_defers_serial_usb_network_sdio_and_pcie_before_shell() {
        assert!(pre_root_runtime_init_deferred_for_profile(
            DriverTaskRuntimeProfile::Pi4Hardware,
            Pi4PreRootNetBootstrapSelection::Wifi,
            SERIAL_DRIVER_TASK_CONTRACT
        ));
        assert!(pre_root_runtime_init_deferred_for_profile(
            DriverTaskRuntimeProfile::Pi4Hardware,
            Pi4PreRootNetBootstrapSelection::Wifi,
            USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT
        ));
        assert!(!pre_root_runtime_init_deferred_for_profile(
            DriverTaskRuntimeProfile::Pi4Hardware,
            Pi4PreRootNetBootstrapSelection::Wifi,
            GENET_DRIVER_TASK_CONTRACT
        ));
        assert!(pre_root_runtime_init_deferred_for_profile(
            DriverTaskRuntimeProfile::Pi4Hardware,
            Pi4PreRootNetBootstrapSelection::Wifi,
            CYW43_WIFI_DRIVER_TASK_CONTRACT
        ));
        assert!(!pre_root_runtime_init_deferred_for_profile(
            DriverTaskRuntimeProfile::Pi4Hardware,
            Pi4PreRootNetBootstrapSelection::Wired,
            CYW43_WIFI_DRIVER_TASK_CONTRACT
        ));
        assert!(pre_root_runtime_init_deferred_for_profile(
            DriverTaskRuntimeProfile::Pi4Hardware,
            Pi4PreRootNetBootstrapSelection::Wired,
            GENET_DRIVER_TASK_CONTRACT
        ));
        assert!(pre_root_runtime_init_deferred_for_profile(
            DriverTaskRuntimeProfile::Pi4Hardware,
            Pi4PreRootNetBootstrapSelection::Wifi,
            SDIO_HOST_DRIVER_TASK_CONTRACT
        ));
        assert!(!pre_root_runtime_init_deferred_for_profile(
            DriverTaskRuntimeProfile::Pi4Hardware,
            Pi4PreRootNetBootstrapSelection::Wired,
            SDIO_HOST_DRIVER_TASK_CONTRACT
        ));
        assert!(pre_root_runtime_init_deferred_for_profile(
            DriverTaskRuntimeProfile::Pi4Hardware,
            Pi4PreRootNetBootstrapSelection::Wifi,
            PCIE_ROOT_DRIVER_TASK_CONTRACT
        ));
        assert!(!pre_root_runtime_init_deferred_for_profile(
            DriverTaskRuntimeProfile::QemuCompatibility,
            Pi4PreRootNetBootstrapSelection::Wifi,
            GENET_DRIVER_TASK_CONTRACT
        ));
        assert!(!pre_root_runtime_init_deferred_for_profile(
            DriverTaskRuntimeProfile::HostTest,
            Pi4PreRootNetBootstrapSelection::Wired,
            GENET_DRIVER_TASK_CONTRACT
        ));
    }

