    #[cfg(feature = "kernel")]
    #[test]
    fn usb_enumeration_hub_progress_does_not_advance_request_on_active_child_marker() {
        let contract = USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT;
        let mut command = DriverTaskCommandRecord::pi4_hot_path(
            0,
            DriverTaskHotPath::UsbKeyboard,
            DriverTaskBudgetGrant::from_contract(contract),
            DriverFrameDescriptor {
                offset: 0,
                len: 0,
                flags: 0,
            },
        );
        command.aux0 = DRIVER_RUNTIME_USB_ENUMERATE_AUX;
        let slot = DriverTaskCommandSlot::new();
        let request = 8;

        record_driver_task_ring_progress(
            &slot,
            DriverTaskRingProgressRecord {
                magic: DRIVER_RUNTIME_RING_PROGRESS_MAGIC,
                sequence: request,
                phase:
                    DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_STATUS_EVENT_IGNORED,
                aux0: command.aux0,
            },
        );
        slot.timeout_resumes.store(63, Ordering::Release);
        assert_eq!(
            driver_task_ring_timeout_keep_decision(
                &slot,
                contract,
                command,
                DriverTaskRingCommandMode::PromptSlice,
                request,
                false,
            ),
            (true, 64)
        );

        record_driver_task_ring_progress(
            &slot,
            DriverTaskRingProgressRecord {
                magic: DRIVER_RUNTIME_RING_PROGRESS_MAGIC,
                sequence: request,
                phase: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_POWER_DONE,
                aux0: command.aux0,
            },
        );
        slot.timeout_resumes.store(127, Ordering::Release);
        assert_eq!(
            driver_task_ring_timeout_keep_decision(
                &slot,
                contract,
                command,
                DriverTaskRingCommandMode::PromptSlice,
                request,
                false,
            ),
            (true, 128)
        );
        assert_eq!(
            driver_task_ring_timeout_keep_active_limit_for_progress(
                &slot,
                contract,
                command,
                DriverTaskRingCommandMode::PromptSlice,
                request,
            ),
            DRIVER_TASK_USB_ENUM_HUB_TIMEOUT_KEEP_ACTIVE_LIMIT
        );

        record_driver_task_ring_progress(
            &slot,
            DriverTaskRingProgressRecord {
                magic: DRIVER_RUNTIME_RING_PROGRESS_MAGIC,
                sequence: request,
                phase: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_TRANSFER_EVENT_SLOT_EMPTY,
                aux0: command.aux0,
            },
        );
        let next_request = request + 1;
        assert!(!driver_task_ring_progress_advanced_for_request(
            &slot,
            DriverTaskRingProgressRecord {
                magic: DRIVER_RUNTIME_RING_PROGRESS_MAGIC,
                sequence: request,
                phase: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_TRANSFER_EVENT_SLOT_EMPTY,
                aux0: command.aux0,
            },
            next_request,
            command.aux0,
        ));
        assert_eq!(
            driver_task_ring_timeout_keep_active_limit_for_progress(
                &slot,
                contract,
                command,
                DriverTaskRingCommandMode::PromptSlice,
                next_request,
            ),
            DRIVER_TASK_USB_ENUM_HUB_EVENT_TIMEOUT_KEEP_ACTIVE_LIMIT
        );
        slot.timeout_resumes.store(
            DRIVER_TASK_USB_ENUM_HUB_TIMEOUT_KEEP_ACTIVE_LIMIT,
            Ordering::Release,
        );
        assert_eq!(
            driver_task_ring_timeout_keep_decision(
                &slot,
                contract,
                command,
                DriverTaskRingCommandMode::PromptSlice,
                next_request,
                false,
            ),
            (true, DRIVER_TASK_USB_ENUM_HUB_TIMEOUT_KEEP_ACTIVE_LIMIT + 1,)
        );

        record_driver_task_ring_progress(
            &slot,
            DriverTaskRingProgressRecord {
                magic: DRIVER_RUNTIME_RING_PROGRESS_MAGIC,
                sequence: request,
                phase: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_RESET_BEGIN,
                aux0: command.aux0,
            },
        );
        assert!(!driver_task_ring_progress_advanced_for_request(
            &slot,
            DriverTaskRingProgressRecord {
                magic: DRIVER_RUNTIME_RING_PROGRESS_MAGIC,
                sequence: request,
                phase: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_RESET_BEGIN,
                aux0: command.aux0,
            },
            next_request,
            command.aux0,
        ));
        assert_eq!(
            driver_task_ring_timeout_keep_active_limit_for_progress(
                &slot,
                contract,
                command,
                DriverTaskRingCommandMode::PromptSlice,
                next_request,
            ),
            DRIVER_TASK_USB_ENUM_HUB_TIMEOUT_KEEP_ACTIVE_LIMIT
        );
        slot.timeout_resumes.store(
            DRIVER_TASK_USB_ENUM_TIMEOUT_KEEP_ACTIVE_LIMIT,
            Ordering::Release,
        );
        assert_eq!(
            driver_task_ring_timeout_keep_decision(
                &slot,
                contract,
                command,
                DriverTaskRingCommandMode::PromptSlice,
                next_request,
                false,
            ),
            (true, DRIVER_TASK_USB_ENUM_TIMEOUT_KEEP_ACTIVE_LIMIT + 1,)
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn usb_enumeration_timeout_preserves_request_progress_across_idle_marker() {
        let slot = DriverTaskCommandSlot::new();
        let request = 8;
        let aux0 = DRIVER_RUNTIME_USB_ENUMERATE_AUX;
        let request_progress = DriverTaskRingProgressRecord {
            magic: DRIVER_RUNTIME_RING_PROGRESS_MAGIC,
            sequence: request,
            phase: DRIVER_RUNTIME_RING_PROGRESS_USB_ROOT_PORT_RESET_BEGIN,
            aux0,
        };

        assert!(driver_task_ring_progress_should_record_for_request(
            &slot,
            request_progress,
            request,
            aux0
        ));
        record_driver_task_ring_progress(&slot, request_progress);

        let idle_progress = DriverTaskRingProgressRecord {
            magic: DRIVER_RUNTIME_RING_PROGRESS_MAGIC,
            sequence: 0,
            phase: DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_POLL_READY,
            aux0: DRIVER_TASK_KEY_USB_LOCAL_SEAT as u32,
        };
        assert!(!driver_task_ring_progress_matches_request(
            idle_progress,
            request,
            aux0
        ));
        assert!(!driver_task_ring_progress_advanced_for_request(
            &slot,
            idle_progress,
            request,
            aux0
        ));
        assert!(!driver_task_ring_progress_should_record_for_request(
            &slot,
            idle_progress,
            request,
            aux0
        ));
        if driver_task_ring_progress_should_record_for_request(&slot, idle_progress, request, aux0)
        {
            record_driver_task_ring_progress(&slot, idle_progress);
        }
        assert_eq!(slot.last_progress_sequence.load(Ordering::Acquire), request);
        assert_eq!(
            slot.last_progress_phase.load(Ordering::Acquire),
            DRIVER_RUNTIME_RING_PROGRESS_USB_ROOT_PORT_RESET_BEGIN
        );
        assert_eq!(slot.last_progress_aux0.load(Ordering::Acquire), aux0);

        let fresh_slot = DriverTaskCommandSlot::new();
        assert!(driver_task_ring_progress_should_record_for_request(
            &fresh_slot,
            idle_progress,
            request,
            aux0
        ));

        let advanced_progress = DriverTaskRingProgressRecord {
            magic: DRIVER_RUNTIME_RING_PROGRESS_MAGIC,
            sequence: request,
            phase: DRIVER_RUNTIME_RING_PROGRESS_USB_DEVICE_ADDRESSED,
            aux0,
        };
        assert!(driver_task_ring_progress_advanced_for_request(
            &slot,
            advanced_progress,
            request,
            aux0
        ));
        assert!(driver_task_ring_progress_should_record_for_request(
            &slot,
            advanced_progress,
            request,
            aux0
        ));
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_root_grant_progress_matches_request_while_aux_carries_grant_id() {
        let slot = DriverTaskCommandSlot::new();
        let request = 73;
        let ready = DriverTaskRingProgressRecord {
            magic: DRIVER_RUNTIME_RING_PROGRESS_MAGIC,
            sequence: request,
            phase: DRIVER_RUNTIME_RING_PROGRESS_ROOT_GRANT_READY,
            aux0: 17,
        };
        assert!(driver_task_ring_progress_matches_request(
            ready,
            request,
            DRIVER_RUNTIME_CYW43_COMMAND_AUX,
        ));
        assert!(driver_task_ring_progress_advanced_for_request(
            &slot,
            ready,
            request,
            DRIVER_RUNTIME_CYW43_COMMAND_AUX,
        ));
        record_driver_task_ring_progress(&slot, ready);
        assert!(cached_driver_task_ring_progress_matches_request(
            &slot,
            request,
            DRIVER_RUNTIME_CYW43_COMMAND_AUX,
        ));
        let accepted = DriverTaskRingProgressRecord {
            phase: DRIVER_RUNTIME_RING_PROGRESS_ROOT_GRANT_ACCEPTED,
            ..ready
        };
        assert!(driver_task_ring_progress_advanced_for_request(
            &slot,
            accepted,
            request,
            DRIVER_RUNTIME_CYW43_COMMAND_AUX,
        ));
        assert!(!driver_task_ring_progress_matches_request(
            DriverTaskRingProgressRecord {
                sequence: request.wrapping_add(1),
                ..ready
            },
            request,
            DRIVER_RUNTIME_CYW43_COMMAND_AUX,
        ));
    }

